-- ===== integrations-local.sql =====
-- LOCAL PRO ONLY. Round 6A (2026-11-13): integration framework for third-party providers.
-- * One connection per owner and provider (hacienda = Hacienda ATV e-invoicing, tilopay = card/SINPE
--   processor). mode mock | sandbox | production; NON-SECRET config only. Secrets live in server
--   environment variables, never here: pro_integration_config_safe() rejects secret-like keys or values
--   (defence in depth; the API also whitelists keys per provider).
-- * Production is never selected automatically: set_mode 'production' needs the caller's explicit typed
--   confirmation AND p_production_allowed (the server passes PRO_INTEGRATIONS_ALLOW_PRODUCTION=1).
--   Without the flag it is refused (42501, hint pro_integration_production_refused).
-- * Immutable history of every connection change, idempotent actionId receipts, CAS by revision.
-- * Outbound request log (redacted summaries only), webhook inbox with idempotency by (provider, event id),
--   rejected deliveries (bad signature) kept apart so a forged id can never block the real event, and a
--   deterministic retry/backoff (30 s × 2^(attempt−1), at most 1 h).
-- Tables: RLS on, service_role only; functions security invoker, executable by service_role only.
begin;

create or replace function public.pro_integration_config_safe(p_value jsonb) returns boolean
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare k text;v jsonb;
begin
 if p_value is null then return true;end if;
 if jsonb_typeof(p_value)='object' then
  for k,v in select * from jsonb_each(p_value) loop
   if k ~* '(secret|passw|pass$|token|authori|api.?key|^key$|_key$|pin$|^pin|p12|pfx|private|cvc|cvv|card.?number|^pan$|cookie|credential)' and v<>to_jsonb('[redactado]'::text) then return false;end if;
   if not public.pro_integration_config_safe(v) then return false;end if;
  end loop;
 elsif jsonb_typeof(p_value)='array' then
  for v in select * from jsonb_array_elements(p_value) loop if not public.pro_integration_config_safe(v) then return false;end if;end loop;
 elsif jsonb_typeof(p_value)='string' then
  -- PEM blocks, long base64 blobs or full card numbers never belong in stored config/logs.
  if p_value#>>'{}' ~ '-----BEGIN' or p_value#>>'{}' ~ '([A-Za-z0-9+/=]{200}){2,}' or p_value#>>'{}' ~ '(^|[^0-9])[0-9]{13,19}([^0-9]|$)' and p_value#>>'{}' !~ '^[0-9]{20,}$' then return false;end if;
 end if;
 return true;
end $$;

create table if not exists public.pro_integration_connections(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('hacienda','tilopay')),
 mode text not null default 'mock' check(mode in('mock','sandbox','production')),
 enabled boolean not null default true,
 config jsonb not null default '{}' check(jsonb_typeof(config)='object' and octet_length(config::text)<=4096 and public.pro_integration_config_safe(config)),
 revision integer not null default 0 check(revision between 0 and 1000000),
 last_test_at timestamptz,last_test_ok boolean,last_test_mode text check(last_test_mode is null or last_test_mode in('mock','sandbox','production')),
 last_test_message text check(last_test_message is null or length(last_test_message)<=300),
 production_confirmed_at timestamptz,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,provider),
 check(mode<>'production' or production_confirmed_at is not null)
);
create table if not exists public.pro_integration_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,provider text not null,action text not null check(action in('set_mode','save_config','enable','disable','test')),
 from_mode text,to_mode text,detail jsonb not null default '{}' check(public.pro_integration_config_safe(detail)),
 created_at timestamptz not null default now(),primary key(owner_id,id)
);
create index if not exists pro_integration_history_recent on public.pro_integration_history(owner_id,provider,created_at desc);
create table if not exists public.pro_integration_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);
-- Outbound request log: what was called, redacted, never a credential, a card number or a full XML.
create table if not exists public.pro_integration_requests(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,provider text not null check(provider in('hacienda','tilopay')),
 mode text not null check(mode in('mock','sandbox','production')),
 operation text not null check(length(operation) between 1 and 60),
 target text not null check(length(target) between 1 and 200 and target !~ '\?'),
 summary jsonb not null default '{}' check(octet_length(summary::text)<=4096 and public.pro_integration_config_safe(summary)),
 status_code integer check(status_code is null or status_code between 0 and 999),
 outcome text not null check(outcome in('ok','error','timeout','refused')),
 duration_ms integer not null default 0 check(duration_ms between 0 and 600000),
 attempt integer not null default 1 check(attempt between 1 and 100),
 correlation text check(correlation is null or length(correlation)<=80),
 created_at timestamptz not null default now(),primary key(owner_id,id)
);
create index if not exists pro_integration_requests_recent on public.pro_integration_requests(owner_id,created_at desc);
-- Webhook inbox: one row per (provider, event id); payload already redacted by the server.
create table if not exists public.pro_integration_webhooks(
 id uuid not null primary key,provider text not null check(provider in('hacienda','tilopay')),
 mode text not null check(mode in('mock','sandbox','production')),
 event_id text not null check(length(event_id) between 1 and 120),
 event_type text not null check(length(event_type) between 1 and 60),
 owner_id uuid references public.profiles(id) on delete cascade,
 payload jsonb not null check(octet_length(payload::text)<=16384 and public.pro_integration_config_safe(payload)),
 status text not null default 'received' check(status in('received','processed','ignored','failed')),
 attempts integer not null default 0 check(attempts between 0 and 100),
 next_attempt_at timestamptz,last_error text check(last_error is null or length(last_error)<=300),
 received_at timestamptz not null default now(),processed_at timestamptz,
 unique(provider,event_id)
);
create index if not exists pro_integration_webhooks_owner on public.pro_integration_webhooks(owner_id,received_at desc);
create index if not exists pro_integration_webhooks_retry on public.pro_integration_webhooks(next_attempt_at) where status='failed';
create table if not exists public.pro_integration_webhook_rejections(
 id uuid not null primary key default gen_random_uuid(),provider text not null,reason text not null check(length(reason) between 1 and 120),
 received_at timestamptz not null default now()
);

create or replace function public.pro_integration_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Integration history, receipts and request log are immutable' using errcode='23514';end $$;
do $$declare n text;begin foreach n in array array['pro_integration_history','pro_integration_actions','pro_integration_requests','pro_integration_webhook_rejections'] loop
 execute format('drop trigger if exists pro_integration_immutable on public.%I',n);
 execute format('create trigger pro_integration_immutable before update on public.%I for each row execute function public.pro_integration_immutable()',n);
end loop;end $$;
-- A webhook row only moves forward; processed/ignored are final; identity and payload never change.
create or replace function public.pro_integration_webhook_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.id<>old.id or new.provider<>old.provider or new.event_id<>old.event_id or new.event_type<>old.event_type or new.payload<>old.payload or new.mode<>old.mode or new.received_at<>old.received_at
  or old.owner_id is not null and new.owner_id is distinct from old.owner_id then raise exception 'Webhook identity is immutable' using errcode='23514';end if;
 if old.status in('processed','ignored') then raise exception 'Webhook already final' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_integration_webhook_guard on public.pro_integration_webhooks;
create trigger pro_integration_webhook_guard before update on public.pro_integration_webhooks for each row execute function public.pro_integration_webhook_guard();

-- Deterministic backoff shared by webhook and submission retries (TS mirror: integrations/retry.ts).
create or replace function public.pro_integration_retry_delay(p_attempt integer) returns interval
language sql immutable security invoker set search_path=public,pg_temp as $$
 select make_interval(secs=>least(30*power(2,greatest(coalesce(p_attempt,1),1)-1),3600)) $$;

create or replace function public.pro_integration_connection_json(p_row public.pro_integration_connections,p_provider text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('provider',p_provider,'mode',coalesce(p_row.mode,'mock'),'enabled',coalesce(p_row.enabled,true),'config',coalesce(p_row.config,'{}'::jsonb),
  'revision',coalesce(p_row.revision,0),'lastTestAt',p_row.last_test_at,'lastTestOk',p_row.last_test_ok,'lastTestMode',p_row.last_test_mode,'lastTestMessage',p_row.last_test_message,
  'productionConfirmedAt',p_row.production_confirmed_at,'updatedAt',p_row.updated_at) $$;

create or replace function public.pro_integration_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare out jsonb:='[]';p text;r public.pro_integration_connections;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 foreach p in array array['hacienda','tilopay'] loop
  select * into r from public.pro_integration_connections where owner_id=p_actor and provider=p;
  if not found then r:=null;end if;
  out:=out||jsonb_build_array(public.pro_integration_connection_json(r,p));
 end loop;
 return jsonb_build_object('connections',out,
  'history',coalesce((select jsonb_agg(jsonb_build_object('provider',h.provider,'action',h.action,'fromMode',h.from_mode,'toMode',h.to_mode,'detail',h.detail,'at',h.created_at) order by h.created_at desc) from (select * from public.pro_integration_history where owner_id=p_actor order by created_at desc limit 20) h),'[]'),
  'requests',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'provider',q.provider,'mode',q.mode,'operation',q.operation,'target',q.target,'summary',q.summary,'statusCode',q.status_code,'outcome',q.outcome,'durationMs',q.duration_ms,'attempt',q.attempt,'correlation',q.correlation,'at',q.created_at) order by q.created_at desc) from (select * from public.pro_integration_requests where owner_id=p_actor order by created_at desc limit 20) q),'[]'),
  'webhooks',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'provider',w.provider,'mode',w.mode,'eventId',w.event_id,'eventType',w.event_type,'status',w.status,'attempts',w.attempts,'nextAttemptAt',w.next_attempt_at,'lastError',w.last_error,'receivedAt',w.received_at,'processedAt',w.processed_at) order by w.received_at desc) from (select * from public.pro_integration_webhooks where owner_id=p_actor order by received_at desc limit 20) w),'[]'));
end $$;

-- Mode of a provider for a server operation: the stored choice (mock by default). The server still checks env keys.
create or replace function public.pro_integration_mode(p_actor uuid,p_provider text) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select case when enabled then mode else 'disabled' end from public.pro_integration_connections where owner_id=p_actor and provider=p_provider),'mock') $$;

create or replace function public.pro_integration_mutate(p_actor uuid,p_input jsonb,p_production_allowed boolean default false) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';prov text:=p_input->>'provider';aid uuid;receipt public.pro_integration_actions;r public.pro_integration_connections;
 next_mode text;rev integer;result jsonb;old_mode text;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or prov not in('hacienda','tilopay') or act not in('set_mode','save_config','enable','disable','test') then raise exception 'Invalid integration action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-integration:'||p_actor::text,0));
 select * into receipt from public.pro_integration_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 insert into public.pro_integration_connections(owner_id,provider,revision) values(p_actor,prov,0) on conflict do nothing;
 select * into r from public.pro_integration_connections where owner_id=p_actor and provider=prov for update;
 old_mode:=r.mode;
 if act<>'test' then
  if jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid revision' using errcode='22023';end if;
  rev:=(p_input->>'revision')::integer;
  -- A never-saved connection reads as revision 0 (defaults), exactly the revision of its first row.
  if rev is distinct from r.revision then raise exception 'Integration changed' using errcode='40001';end if;
 end if;
 if act='set_mode' then
  next_mode:=p_input->>'mode';
  if next_mode not in('mock','sandbox','production') then raise exception 'Invalid mode' using errcode='22023';end if;
  if next_mode='production' then
   if not coalesce(p_production_allowed,false) then raise exception 'Production integrations are not allowed on this server' using errcode='42501',hint='pro_integration_production_refused';end if;
   if p_input->>'confirm' is distinct from 'ACTIVAR PRODUCCION' then raise exception 'Production needs explicit confirmation' using errcode='22023',hint='pro_integration_production_confirm';end if;
  end if;
  update public.pro_integration_connections set mode=next_mode,production_confirmed_at=case when next_mode='production' then now() else null end,revision=revision+1,updated_at=now()
   where owner_id=p_actor and provider=prov returning * into r;
 elsif act='save_config' then
  if jsonb_typeof(p_input->'config')<>'object' or not public.pro_integration_config_safe(p_input->'config') then raise exception 'Config must be non-secret' using errcode='22023',hint='pro_integration_secret_config';end if;
  update public.pro_integration_connections set config=p_input->'config',revision=revision+1,updated_at=now() where owner_id=p_actor and provider=prov returning * into r;
 elsif act in('enable','disable') then
  update public.pro_integration_connections set enabled=(act='enable'),revision=revision+1,updated_at=now() where owner_id=p_actor and provider=prov returning * into r;
 else
  -- test: the server ran «Probar conexión» against the adapter of the resolved mode and reports it.
  if jsonb_typeof(p_input->'ok')<>'boolean' or p_input->>'testMode' not in('mock','sandbox','production') or length(coalesce(p_input->>'message',''))>300 then raise exception 'Invalid test result' using errcode='22023';end if;
  update public.pro_integration_connections set last_test_at=now(),last_test_ok=(p_input->>'ok')::boolean,last_test_mode=p_input->>'testMode',last_test_message=nullif(p_input->>'message','')
   where owner_id=p_actor and provider=prov returning * into r;
 end if;
 insert into public.pro_integration_history(owner_id,id,provider,action,from_mode,to_mode,detail) values(p_actor,aid,prov,act,old_mode,r.mode,
  case when act='save_config' then jsonb_build_object('keys',(select coalesce(jsonb_agg(k order by k),'[]') from jsonb_object_keys(p_input->'config') k)) when act='test' then jsonb_build_object('ok',p_input->'ok','mode',p_input->>'testMode') else '{}'::jsonb end);
 result:=public.pro_integration_connection_json(r,prov);
 insert into public.pro_integration_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Outbound log (server writes it after each adapter call; the summary is redacted in TS and checked here).
create or replace function public.pro_integration_log(p_actor uuid,p_entry jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare rid uuid:=gen_random_uuid();
begin
 if not public.pro_integration_config_safe(p_entry->'summary') then raise exception 'Log summary must be redacted' using errcode='22023',hint='pro_integration_secret_config';end if;
 insert into public.pro_integration_requests(owner_id,id,provider,mode,operation,target,summary,status_code,outcome,duration_ms,attempt,correlation)
 values(p_actor,rid,p_entry->>'provider',p_entry->>'mode',p_entry->>'operation',p_entry->>'target',coalesce(p_entry->'summary','{}'),(p_entry->>'statusCode')::integer,p_entry->>'outcome',
  coalesce((p_entry->>'durationMs')::integer,0),coalesce((p_entry->>'attempt')::integer,1),left(p_entry->>'correlation',80));
 return rid;
exception when check_violation or invalid_text_representation or not_null_violation or foreign_key_violation then raise exception 'Invalid log entry' using errcode='22023';
end $$;

-- Webhook inbox: idempotent by (provider, event id). Returns the row and whether it was a duplicate.
create or replace function public.pro_integration_webhook_receive(p_provider text,p_mode text,p_event_id text,p_event_type text,p_owner uuid,p_payload jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare w public.pro_integration_webhooks;dup boolean:=false;
begin
 if not public.pro_integration_config_safe(p_payload) then raise exception 'Webhook payload must be redacted' using errcode='22023',hint='pro_integration_secret_config';end if;
 insert into public.pro_integration_webhooks(id,provider,mode,event_id,event_type,owner_id,payload) values(gen_random_uuid(),p_provider,p_mode,p_event_id,p_event_type,p_owner,p_payload)
 on conflict(provider,event_id) do nothing returning * into w;
 if w.id is null then
  dup:=true;select * into w from public.pro_integration_webhooks where provider=p_provider and event_id=p_event_id;
  if w.event_type<>p_event_type or w.payload<>p_payload then raise exception 'Webhook event id reused with a different payload' using errcode='22023',hint='pro_integration_webhook_conflict';end if;
 end if;
 return jsonb_build_object('id',w.id,'duplicate',dup,'status',w.status,'attempts',w.attempts);
end $$;
create or replace function public.pro_integration_webhook_reject(p_provider text,p_reason text) returns void
language sql security invoker set search_path=public,pg_temp as $$
 insert into public.pro_integration_webhook_rejections(provider,reason) values(left(coalesce(p_provider,'?'),40),left(coalesce(p_reason,'invalid'),120)) $$;
-- A processing failure keeps the event for a retry with backoff; it never loses or duplicates it.
create or replace function public.pro_integration_webhook_fail(p_id uuid,p_error text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare w public.pro_integration_webhooks;
begin
 update public.pro_integration_webhooks set status='failed',attempts=attempts+1,next_attempt_at=now()+public.pro_integration_retry_delay(attempts+1),last_error=left(coalesce(p_error,'error'),300)
 where id=p_id and status in('received','failed') returning * into w;
 return jsonb_build_object('id',w.id,'status',w.status,'attempts',w.attempts,'nextAttemptAt',w.next_attempt_at);
end $$;

do $$declare n text;begin foreach n in array array['pro_integration_connections','pro_integration_history','pro_integration_actions','pro_integration_requests','pro_integration_webhooks','pro_integration_webhook_rejections'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_integration\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_integration_immutable(%' and f::text not like 'pro_integration_webhook_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== einvoice-local.sql =====
-- LOCAL PRO ONLY. Round 6A (2026-11-13): Hacienda electronic invoices (Costa Rica, v4.4) built from an
-- existing invoice DRAFT. Factura Electrónica (01), Nota de Crédito (03) referencing an accepted
-- original, Tiquete Electrónico (04). The draft stays an internal draft until a document is emitted;
-- emitted documents are immutable.
-- * Emisor settings per owner (identification, name, commercial name, economic activity, location
--   codes, branch/terminal, «proveedor de sistemas»), CAS by revision.
-- * Consecutivo (20 digits: branch 3 + terminal 5 + type 2 + number 10) allocated gapless per owner,
--   branch, terminal and type; clave (50 digits: 506 + DDMMYY in America/Costa_Rica + emisor id padded to
--   12 + consecutivo + situación 1 + 8-digit security code) composed HERE, so its format is enforced.
-- * State machine borrador → firmado → enviado → recibido → aceptado | rechazado, with error (retry with
--   backoff) — enforced by a trigger; XML, signed XML, totals, clave and snapshot are frozen once signed;
--   aceptado/rechazado are final; every transition is an immutable event.
-- * An emitted FE/TE (any state except rechazado) locks the draft content (hint pro_einvoice_emitted);
--   a rejected document frees it and the next emission takes a NEW consecutivo.
-- * Credit notes reference an ACCEPTED FE/TE of the same draft; the sum of active credit notes never
--   exceeds the original total.
-- No real call to Hacienda happens in SQL; the server adapter (mock by default) reports each step.
begin;

create table if not exists public.pro_einvoice_settings(
 owner_id uuid not null primary key references public.profiles(id) on delete cascade,
 id_type text not null check(id_type in('01','02','03','04')),
 id_number text not null,
 name text not null check(length(name) between 5 and 100),
 commercial_name text check(commercial_name is null or length(commercial_name) between 3 and 80),
 activity_code text not null check(activity_code ~ '^[0-9]{6}$'),
 province text not null check(province ~ '^[1-7]$'),canton text not null check(canton ~ '^[0-9]{2}$'),district text not null check(district ~ '^[0-9]{2}$'),
 barrio text check(barrio is null or length(barrio) between 5 and 50),
 other_signs text not null check(length(other_signs) between 5 and 250),
 phone text check(phone is null or phone ~ '^[0-9]{8,20}$'),
 email text not null check(length(email) between 3 and 160 and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
 branch text not null default '001' check(branch ~ '^[0-9]{3}$' and branch<>'000'),
 terminal text not null default '00001' check(terminal ~ '^[0-9]{5}$' and terminal<>'00000'),
 provider_systems text not null check(length(provider_systems) between 9 and 20 and provider_systems ~ '^[A-Za-z0-9]+$'),
 revision integer not null default 1 check(revision>=1),
 updated_at timestamptz not null default now(),
 check(case id_type when '01' then id_number ~ '^[1-9][0-9]{8}$' when '02' then id_number ~ '^[A-Za-z0-9]{10}$' when '03' then id_number ~ '^[1-9][0-9]{10,11}$' else id_number ~ '^[0-9]{10}$' end)
);
create table if not exists public.pro_einvoice_sequences(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 branch text not null,terminal text not null,doc_type text not null check(doc_type in('01','03','04')),
 last_number bigint not null default 0 check(last_number between 0 and 9999999999),
 primary key(owner_id,branch,terminal,doc_type)
);
create table if not exists public.pro_einvoice_documents(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,draft_id uuid not null,
 doc_type text not null check(doc_type in('01','03','04')),
 mode text not null check(mode in('mock','sandbox','production')),
 clave text not null check(clave ~ '^506[0-9]{6}[A-Za-z0-9]{12}[0-9]{20}[123][0-9]{8}$'),
 consecutivo text not null check(consecutivo ~ '^[0-9]{3}[0-9]{5}(01|03|04)[0-9]{10}$'),
 issued_at timestamptz not null,
 status text not null default 'borrador' check(status in('borrador','firmado','enviado','recibido','aceptado','rechazado','error')),
 xml text,xml_sha256 text check(xml_sha256 is null or xml_sha256 ~ '^[a-f0-9]{64}$'),
 signed_xml text,signed_sha256 text check(signed_sha256 is null or signed_sha256 ~ '^[a-f0-9]{64}$'),
 signer text check(signer is null or signer in('mock','p12')),
 response_xml text,response_code integer check(response_code is null or response_code in(1,2,3)),
 response_message text check(response_message is null or length(response_message)<=2000),
 total_cents bigint not null check(total_cents between 0 and 10000000000),
 tax_cents bigint not null check(tax_cents between 0 and 10000000000),
 receiver_name text,receiver_id_type text,receiver_id text,
 reference_document_id uuid,reference_code text check(reference_code is null or reference_code in('01','02')),
 reference_reason text check(reference_reason is null or length(reference_reason) between 5 and 180),
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and octet_length(snapshot::text)<=262144),
 attempts integer not null default 0 check(attempts between 0 and 100),
 next_attempt_at timestamptz,last_error text check(last_error is null or length(last_error)<=300),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,clave),unique(owner_id,consecutivo),
 foreign key(owner_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(owner_id,reference_document_id) references public.pro_einvoice_documents(owner_id,id),
 check((doc_type='03')=(reference_document_id is not null and reference_code is not null and reference_reason is not null)),
 check(substr(clave,22,20)=consecutivo),
 check(status='borrador' or xml is not null and signed_xml is not null and xml_sha256 is not null and signed_sha256 is not null and signer is not null),
 check(status not in('aceptado','rechazado') or response_code is not null)
);
create index if not exists pro_einvoice_documents_draft on public.pro_einvoice_documents(owner_id,draft_id,created_at desc);
create index if not exists pro_einvoice_documents_retry on public.pro_einvoice_documents(next_attempt_at) where status='error';
-- One live FE/TE per draft (rejected ones do not count: Hacienda considers them never issued).
create unique index if not exists pro_einvoice_documents_one_live on public.pro_einvoice_documents(owner_id,draft_id) where doc_type in('01','04') and status<>'rechazado';
create table if not exists public.pro_einvoice_events(
 owner_id uuid not null,document_id uuid not null,id bigint generated always as identity,
 from_status text,to_status text not null,detail jsonb not null default '{}',created_at timestamptz not null default now(),
 primary key(owner_id,document_id,id),foreign key(owner_id,document_id) references public.pro_einvoice_documents(owner_id,id) on delete cascade
);
create table if not exists public.pro_einvoice_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input_hash text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);

create or replace function public.pro_einvoice_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Electronic invoice events and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_einvoice_events_immutable on public.pro_einvoice_events;
create trigger pro_einvoice_events_immutable before update on public.pro_einvoice_events for each row execute function public.pro_einvoice_immutable();
drop trigger if exists pro_einvoice_actions_immutable on public.pro_einvoice_actions;
create trigger pro_einvoice_actions_immutable before update on public.pro_einvoice_actions for each row execute function public.pro_einvoice_immutable();

-- State machine + freeze. Transition table (anything else 23514):
--   borrador→firmado · firmado→enviado|error · enviado→recibido|aceptado|rechazado|error
--   recibido→aceptado|rechazado|error · error→enviado|recibido|aceptado|rechazado · aceptado/rechazado final.
create or replace function public.pro_einvoice_document_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.status in('aceptado','rechazado') then raise exception 'Emitted document is final and immutable' using errcode='23514';end if;
 if new.status<>old.status and not(
   old.status='borrador' and new.status='firmado' or old.status='firmado' and new.status in('enviado','error')
   or old.status='enviado' and new.status in('recibido','aceptado','rechazado','error') or old.status='recibido' and new.status in('aceptado','rechazado','error')
   or old.status='error' and new.status in('enviado','recibido','aceptado','rechazado')) then
  raise exception 'Invalid electronic invoice transition % → %',old.status,new.status using errcode='23514';
 end if;
 if new.owner_id<>old.owner_id or new.id<>old.id or new.draft_id<>old.draft_id or new.doc_type<>old.doc_type or new.mode<>old.mode or new.clave<>old.clave or new.consecutivo<>old.consecutivo
  or new.issued_at<>old.issued_at or new.total_cents<>old.total_cents or new.tax_cents<>old.tax_cents or new.snapshot<>old.snapshot
  or new.reference_document_id is distinct from old.reference_document_id or new.reference_code is distinct from old.reference_code or new.reference_reason is distinct from old.reference_reason
  or new.receiver_name is distinct from old.receiver_name or new.receiver_id is distinct from old.receiver_id or new.receiver_id_type is distinct from old.receiver_id_type or new.created_at<>old.created_at then
  raise exception 'Electronic invoice identity is immutable' using errcode='23514';
 end if;
 if old.status<>'borrador' and (new.xml is distinct from old.xml or new.signed_xml is distinct from old.signed_xml or new.xml_sha256 is distinct from old.xml_sha256 or new.signed_sha256 is distinct from old.signed_sha256 or new.signer is distinct from old.signer) then
  raise exception 'Signed XML is immutable' using errcode='23514';
 end if;
 if new.status='firmado' and old.status='borrador' and (encode(sha256(convert_to(new.xml,'UTF8')),'hex')<>new.xml_sha256 or encode(sha256(convert_to(new.signed_xml,'UTF8')),'hex')<>new.signed_sha256 or position(new.clave in new.xml)=0 or position(new.consecutivo in new.xml)=0) then
  raise exception 'Signed XML does not match its digest or clave' using errcode='22023',hint='pro_einvoice_xml_mismatch';
 end if;
 new.updated_at:=now();
 return new;
end $$;
drop trigger if exists pro_einvoice_document_guard on public.pro_einvoice_documents;
create trigger pro_einvoice_document_guard before update on public.pro_einvoice_documents for each row execute function public.pro_einvoice_document_guard();
create or replace function public.pro_einvoice_document_event() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='INSERT' or new.status<>old.status then
  insert into public.pro_einvoice_events(owner_id,document_id,from_status,to_status,detail) values(new.owner_id,new.id,case when tg_op='INSERT' then null else old.status end,new.status,
   jsonb_strip_nulls(jsonb_build_object('attempts',new.attempts,'error',case when new.status='error' then new.last_error end,'responseCode',new.response_code)));
 end if;
 return null;
end $$;
drop trigger if exists pro_einvoice_document_event on public.pro_einvoice_documents;
create trigger pro_einvoice_document_event after insert or update on public.pro_einvoice_documents for each row execute function public.pro_einvoice_document_event();

-- The draft remains an internal draft until emitted; once a live FE/TE exists its content is locked.
create or replace function public.pro_einvoice_draft_lock() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-'updated_at')<>(to_jsonb(old)-'updated_at') and exists(select 1 from public.pro_einvoice_documents d where d.owner_id=old.user_id and d.draft_id=old.id and d.doc_type in('01','04') and d.status<>'rechazado') then
  raise exception 'Draft already emitted as an electronic document' using errcode='22023',hint='pro_einvoice_emitted';
 end if;
 return new;
end $$;
drop trigger if exists pro_einvoice_draft_lock on public.pro_invoice_drafts;
create trigger pro_einvoice_draft_lock before update on public.pro_invoice_drafts for each row execute function public.pro_einvoice_draft_lock();

create or replace function public.pro_einvoice_settings_json(p_row public.pro_einvoice_settings) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_row.owner_id is null then null else jsonb_build_object('idType',p_row.id_type,'idNumber',p_row.id_number,'name',p_row.name,'commercialName',coalesce(p_row.commercial_name,''),
  'activityCode',p_row.activity_code,'province',p_row.province,'canton',p_row.canton,'district',p_row.district,'barrio',coalesce(p_row.barrio,''),'otherSigns',p_row.other_signs,
  'phone',coalesce(p_row.phone,''),'email',p_row.email,'branch',p_row.branch,'terminal',p_row.terminal,'providerSystems',p_row.provider_systems) end $$;

create or replace function public.pro_einvoice_document_json(p_doc public.pro_einvoice_documents,p_full boolean default false) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_doc.id,'draftId',p_doc.draft_id,'docType',p_doc.doc_type,'mode',p_doc.mode,'clave',p_doc.clave,'consecutivo',p_doc.consecutivo,'issuedAt',p_doc.issued_at,
  'status',p_doc.status,'responseCode',p_doc.response_code,'responseMessage',p_doc.response_message,'totalCents',p_doc.total_cents,'taxCents',p_doc.tax_cents,
  'receiverName',p_doc.receiver_name,'referenceDocumentId',p_doc.reference_document_id,'referenceCode',p_doc.reference_code,'referenceReason',p_doc.reference_reason,
  'attempts',p_doc.attempts,'nextAttemptAt',p_doc.next_attempt_at,'lastError',p_doc.last_error,'signer',p_doc.signer,'hasXml',p_doc.signed_xml is not null,'hasResponse',p_doc.response_xml is not null,
  'createdAt',p_doc.created_at,'updatedAt',p_doc.updated_at,
  'events',coalesce((select jsonb_agg(jsonb_build_object('from',e.from_status,'to',e.to_status,'detail',e.detail,'at',e.created_at) order by e.id) from public.pro_einvoice_events e where e.owner_id=p_doc.owner_id and e.document_id=p_doc.id),'[]'))
  ||case when p_full then jsonb_build_object('xml',p_doc.xml,'signedXml',p_doc.signed_xml,'responseXml',p_doc.response_xml,'snapshot',p_doc.snapshot) else '{}'::jsonb end $$;

-- Owner read for one draft: settings, documents (newest first) and the credit already noted per original.
create or replace function public.pro_einvoice_read(p_actor uuid,p_draft uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare s public.pro_einvoice_settings;d public.pro_invoice_drafts;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into s from public.pro_einvoice_settings where owner_id=p_actor;
 if p_draft is null then return jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',coalesce(s.revision,0));end if;
 select * into d from public.pro_invoice_drafts where user_id=p_actor and id=p_draft;
 if not found then return null;end if;
 return jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',coalesce(s.revision,0),'draftRevision',d.revision,'draftTotalCents',d.total_cents,
  'documents',coalesce((select jsonb_agg(public.pro_einvoice_document_json(x) order by x.created_at desc) from public.pro_einvoice_documents x where x.owner_id=p_actor and x.draft_id=d.id),'[]'),
  'credited',coalesce((select jsonb_object_agg(o.id,(select coalesce(sum(n.total_cents),0) from public.pro_einvoice_documents n where n.owner_id=p_actor and n.reference_document_id=o.id and n.status<>'rechazado')) from public.pro_einvoice_documents o where o.owner_id=p_actor and o.draft_id=d.id and o.doc_type in('01','04')),'{}'));
end $$;
create or replace function public.pro_einvoice_document_read(p_actor uuid,p_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare x public.pro_einvoice_documents;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into x from public.pro_einvoice_documents where owner_id=p_actor and id=p_id;
 if not found then return null;end if;
 return public.pro_einvoice_document_json(x,true);
end $$;

create or replace function public.pro_einvoice_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_einvoice_actions;h text:=md5(p_input::text);s public.pro_einvoice_settings;d public.pro_invoice_drafts;x public.pro_einvoice_documents;
 o public.pro_einvoice_documents;dtype text;num bigint;cons text;clave text;issued timestamptz;sec text;result jsonb;st text;credited bigint;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' then raise exception 'Invalid input' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-einvoice:'||p_actor::text,0));
 select * into receipt from public.pro_einvoice_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input_hash<>h then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;

 if act='save_settings' then
  select * into s from public.pro_einvoice_settings where owner_id=p_actor for update;
  if jsonb_typeof(p_input->'revision')<>'number' or (p_input->>'revision')::integer<>coalesce(s.revision,0) then raise exception 'Settings changed' using errcode='40001';end if;
  insert into public.pro_einvoice_settings(owner_id,id_type,id_number,name,commercial_name,activity_code,province,canton,district,barrio,other_signs,phone,email,branch,terminal,provider_systems,revision)
  values(p_actor,p_input#>>'{settings,idType}',p_input#>>'{settings,idNumber}',p_input#>>'{settings,name}',nullif(p_input#>>'{settings,commercialName}',''),p_input#>>'{settings,activityCode}',
   p_input#>>'{settings,province}',p_input#>>'{settings,canton}',p_input#>>'{settings,district}',nullif(p_input#>>'{settings,barrio}',''),p_input#>>'{settings,otherSigns}',nullif(p_input#>>'{settings,phone}',''),
   p_input#>>'{settings,email}',coalesce(p_input#>>'{settings,branch}','001'),coalesce(p_input#>>'{settings,terminal}','00001'),p_input#>>'{settings,providerSystems}',1)
  on conflict(owner_id) do update set id_type=excluded.id_type,id_number=excluded.id_number,name=excluded.name,commercial_name=excluded.commercial_name,activity_code=excluded.activity_code,
   province=excluded.province,canton=excluded.canton,district=excluded.district,barrio=excluded.barrio,other_signs=excluded.other_signs,phone=excluded.phone,email=excluded.email,
   branch=excluded.branch,terminal=excluded.terminal,provider_systems=excluded.provider_systems,revision=pro_einvoice_settings.revision+1,updated_at=now()
  returning * into s;
  result:=jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',s.revision);

 elsif act='reserve' then
  dtype:=p_input->>'docType';
  if dtype not in('01','03','04') or p_input->>'mode' not in('mock','sandbox','production') or p_input->>'securityCode' !~ '^[0-9]{8}$' or jsonb_typeof(p_input->'snapshot')<>'object' then raise exception 'Invalid reservation' using errcode='22023';end if;
  select * into s from public.pro_einvoice_settings where owner_id=p_actor;
  if not found then raise exception 'Emisor settings missing' using errcode='22023',hint='pro_einvoice_settings';end if;
  if jsonb_typeof(p_input->'settingsRevision')<>'number' or (p_input->>'settingsRevision')::integer<>s.revision then raise exception 'Settings changed' using errcode='40001';end if;
  select * into d from public.pro_invoice_drafts where user_id=p_actor and id=(p_input->>'draftId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if jsonb_typeof(p_input->'draftRevision')<>'number' or (p_input->>'draftRevision')::integer<>d.revision then raise exception 'Draft changed' using errcode='40001';end if;
  if exists(select 1 from public.pro_invoice_draft_management m where m.user_id=p_actor and m.draft_id=d.id and m.archived) then raise exception 'Archived draft' using errcode='22023',hint='pro_einvoice_archived';end if;
  if dtype in('01','04') then
   if exists(select 1 from public.pro_einvoice_documents where owner_id=p_actor and draft_id=d.id and doc_type in('01','04') and status<>'rechazado') then raise exception 'Draft already emitted' using errcode='40001',hint='pro_einvoice_emitted';end if;
   if (p_input->>'totalCents')::bigint<>d.total_cents then raise exception 'Totals do not match the draft' using errcode='22023',hint='pro_einvoice_totals';end if;
  else
   select * into o from public.pro_einvoice_documents where owner_id=p_actor and id=(p_input->>'referenceDocumentId')::uuid and draft_id=d.id and doc_type in('01','04');
   if not found then raise exception 'Unknown original' using errcode='22023',hint='pro_einvoice_reference';end if;
   if o.status<>'aceptado' then raise exception 'Original not accepted' using errcode='22023',hint='pro_einvoice_reference_state';end if;
   if p_input->>'referenceCode' not in('01','02') or length(coalesce(p_input->>'referenceReason',''))<5 then raise exception 'Invalid reference' using errcode='22023';end if;
   select coalesce(sum(total_cents),0) into credited from public.pro_einvoice_documents where owner_id=p_actor and reference_document_id=o.id and status<>'rechazado';
   if (p_input->>'totalCents')::bigint<1 or (p_input->>'totalCents')::bigint>o.total_cents-credited then raise exception 'Credit exceeds original' using errcode='22023',hint='pro_einvoice_credit_exceeds';end if;
   if p_input->>'referenceCode'='01' and (credited>0 or (p_input->>'totalCents')::bigint<>o.total_cents) then raise exception 'Full cancellation must credit the whole original' using errcode='22023',hint='pro_einvoice_credit_exceeds';end if;
  end if;
  insert into public.pro_einvoice_sequences(owner_id,branch,terminal,doc_type) values(p_actor,s.branch,s.terminal,dtype) on conflict do nothing;
  update public.pro_einvoice_sequences set last_number=case when last_number>=9999999999 then 1 else last_number+1 end where owner_id=p_actor and branch=s.branch and terminal=s.terminal and doc_type=dtype returning last_number into num;
  cons:=s.branch||s.terminal||dtype||lpad(num::text,10,'0');
  issued:=date_trunc('second',now());
  sec:=p_input->>'securityCode';
  clave:='506'||to_char(issued at time zone 'America/Costa_Rica','DDMMYY')||lpad(s.id_number,12,'0')||cons||'1'||sec;
  insert into public.pro_einvoice_documents(owner_id,id,draft_id,doc_type,mode,clave,consecutivo,issued_at,total_cents,tax_cents,receiver_name,receiver_id_type,receiver_id,reference_document_id,reference_code,reference_reason,snapshot)
  values(p_actor,aid,d.id,dtype,p_input->>'mode',clave,cons,issued,(p_input->>'totalCents')::bigint,(p_input->>'taxCents')::bigint,nullif(p_input->>'receiverName',''),nullif(p_input->>'receiverIdType',''),nullif(p_input->>'receiverId',''),
   case when dtype='03' then o.id end,case when dtype='03' then p_input->>'referenceCode' end,case when dtype='03' then p_input->>'referenceReason' end,p_input->'snapshot') returning * into x;
  result:=public.pro_einvoice_document_json(x)||jsonb_build_object('settings',public.pro_einvoice_settings_json(s));

 elsif act in('sign','submitted','status') then
  select * into x from public.pro_einvoice_documents where owner_id=p_actor and id=(p_input->>'documentId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if act='sign' then
   if x.status<>'borrador' then raise exception 'Already signed' using errcode='40001';end if;
   if p_input->>'signer' not in('mock','p12') then raise exception 'Invalid signer' using errcode='22023';end if;
   update public.pro_einvoice_documents set status='firmado',xml=p_input->>'xml',xml_sha256=p_input->>'xmlSha256',signed_xml=p_input->>'signedXml',signed_sha256=p_input->>'signedSha256',signer=p_input->>'signer'
   where owner_id=p_actor and id=x.id returning * into x;
  elsif act='submitted' then
   if x.status not in('firmado','error') then raise exception 'Not ready to send' using errcode='40001';end if;
   if p_input->>'outcome'='sent' then
    update public.pro_einvoice_documents set status='enviado',attempts=attempts+1,next_attempt_at=null,last_error=null where owner_id=p_actor and id=x.id returning * into x;
   elsif p_input->>'outcome'='error' then
    update public.pro_einvoice_documents set status='error',attempts=attempts+1,next_attempt_at=now()+public.pro_integration_retry_delay(attempts+1),last_error=left(coalesce(p_input->>'message','Error'),300) where owner_id=p_actor and id=x.id returning * into x;
   else raise exception 'Invalid outcome' using errcode='22023';end if;
  else
   st:=p_input->>'state';
   if st not in('recibido','procesando','aceptado','rechazado','error') then raise exception 'Invalid state' using errcode='22023';end if;
   if x.status not in('enviado','recibido','error') then raise exception 'Not sent' using errcode='40001';end if;
   if st='procesando' then st:='recibido';end if;
   if st in('aceptado','rechazado') and (p_input->>'responseXml' is null or (p_input->>'responseCode')::integer not in(1,2,3)) then raise exception 'Final state needs the response' using errcode='22023';end if;
   if st=x.status then
    result:=public.pro_einvoice_document_json(x);
   else
    update public.pro_einvoice_documents set status=st,response_xml=case when st in('aceptado','rechazado') then p_input->>'responseXml' else response_xml end,
     response_code=case when st in('aceptado','rechazado') then (p_input->>'responseCode')::integer else response_code end,
     response_message=coalesce(left(p_input->>'message',2000),response_message),
     attempts=case when st='error' then attempts+1 else attempts end,
     next_attempt_at=case when st='error' then now()+public.pro_integration_retry_delay(attempts+1) else null end,
     last_error=case when st='error' then left(coalesce(p_input->>'message','Error'),300) else null end
    where owner_id=p_actor and id=x.id returning * into x;
   end if;
  end if;
  result:=public.pro_einvoice_document_json(x);
 else raise exception 'Invalid electronic invoice action' using errcode='22023';end if;
 insert into public.pro_einvoice_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,h,result);
 return result;
exception when check_violation then
 if sqlerrm like '%immutable%' or sqlerrm like '%transition%' or sqlerrm like '%final%' then raise;end if;
 raise exception 'Invalid electronic invoice data: %',sqlerrm using errcode='22023',hint='pro_einvoice_invalid';
end $$;

do $$declare n text;begin foreach n in array array['pro_einvoice_settings','pro_einvoice_sequences','pro_einvoice_documents','pro_einvoice_events','pro_einvoice_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_einvoice\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_einvoice_immutable(%' and f::text not like 'pro_einvoice_document_guard(%' and f::text not like 'pro_einvoice_document_event(%' and f::text not like 'pro_einvoice_draft_lock(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== einvoice-pipeline-local.sql =====
-- LOCAL PRO ONLY. Ronda F2-A (2026-11-19): electronic-invoice PIPELINE behind a provider adapter (row 58).
-- Extends einvoice-local.sql (Round 6A) without touching its rows:
-- * Debit note (02) referencing an ACCEPTED FE/TE of the same draft (reference code 02, never capped).
-- * Hacienda's asynchronous answer modelled as its own state: enviado → recibido → procesando → aceptado | rechazado,
--   with error (retry with backoff) at any non-final step; «duplicate» submissions (Hacienda: «ya fue recibido»)
--   are recorded as received, never as a second document.
-- * Provider responses: one immutable row per adapter call (provider, mode, operation, attempt, HTTP status,
--   outcome, state, message, SHA-256 of the body). The XML payload stays inline (text, frozen once signed) and is
--   referenced by (owner_id, clave) + xml_sha256/signed_sha256.
-- * Per-emisor provider (mock | hacienda-sandbox | gti). The MODE is resolved by the server on every call and is
--   recorded per document; it is never chosen by the browser.
-- * Receiver messages (MensajeReceptor 05 aceptación, 06 aceptación parcial, 07 rechazo) for documents RECEIVED from
--   suppliers, with their own gapless consecutivo per branch/terminal/type, the same state machine and history.
-- Security as neighbours: RLS on, no anon/authenticated grants, service_role only, security invoker, owner gate
-- (pro_private_work_tools_enabled), idempotent actionId receipts, immutable history and responses. The route
-- (/api/pro/invoice-einvoice) only lets the owner, Administrador and Gerente in.
-- Nothing here calls Hacienda or a provider: the server adapter (mock by default) reports each step.
begin;

-- 1) Provider per emisor (older rows → mock).
alter table public.pro_einvoice_settings add column if not exists provider text not null default 'mock';
alter table public.pro_einvoice_documents add column if not exists provider text not null default 'mock';
do $$begin
 if not exists(select 1 from pg_constraint where conname='pro_einvoice_f2a_settings_provider' and conrelid='public.pro_einvoice_settings'::regclass) then
  alter table public.pro_einvoice_settings add constraint pro_einvoice_f2a_settings_provider check(provider in('mock','hacienda-sandbox','gti'));end if;
 if not exists(select 1 from pg_constraint where conname='pro_einvoice_f2a_documents_provider' and conrelid='public.pro_einvoice_documents'::regclass) then
  alter table public.pro_einvoice_documents add constraint pro_einvoice_f2a_documents_provider check(provider in('mock','hacienda-sandbox','gti'));end if;
end $$;

-- 2) Widen the Round 6A checks that enumerate document types and states (replaced by named f2a checks).
do $$declare c record;begin
 for c in select conname,conrelid::regclass rel,pg_get_constraintdef(oid) def from pg_constraint
  where contype='c' and conrelid in('public.pro_einvoice_documents'::regclass,'public.pro_einvoice_sequences'::regclass) and conname not like 'pro\_einvoice\_f2a\_%' loop
  if c.def like '%doc_type%''03''%' or c.def like '%01|03|04%' or c.def like '%''borrador''%''procesando''%' or (c.def like '%status%' and c.def like '%''firmado''%' and c.def like '%''error''%' and c.def not like '%xml%') then
   execute format('alter table %s drop constraint %I',c.rel,c.conname);
  end if;
 end loop;
 if not exists(select 1 from pg_constraint where conname='pro_einvoice_f2a_doc_type' and conrelid='public.pro_einvoice_documents'::regclass) then
  alter table public.pro_einvoice_documents add constraint pro_einvoice_f2a_doc_type check(doc_type in('01','02','03','04'));
  alter table public.pro_einvoice_documents add constraint pro_einvoice_f2a_consecutivo check(consecutivo ~ '^[0-9]{3}[0-9]{5}(01|02|03|04)[0-9]{10}$');
  alter table public.pro_einvoice_documents add constraint pro_einvoice_f2a_status check(status in('borrador','firmado','enviado','recibido','procesando','aceptado','rechazado','error'));
  alter table public.pro_einvoice_documents add constraint pro_einvoice_f2a_reference check((doc_type in('02','03'))=(reference_document_id is not null and reference_code is not null and reference_reason is not null));
 end if;
 if not exists(select 1 from pg_constraint where conname='pro_einvoice_f2a_sequence_type' and conrelid='public.pro_einvoice_sequences'::regclass) then
  alter table public.pro_einvoice_sequences add constraint pro_einvoice_f2a_sequence_type check(doc_type in('01','02','03','04','05','06','07'));
 end if;
end $$;

-- 3) Provider responses (append-only).
create table if not exists public.pro_einvoice_receiver_messages(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 received_clave text not null check(received_clave ~ '^506[0-9]{6}[A-Za-z0-9]{12}[0-9]{20}[123][0-9]{8}$'),
 emisor_id_type text not null check(emisor_id_type in('01','02','03','04','05')),
 emisor_id text not null check(emisor_id ~ '^[A-Za-z0-9]{9,20}$'),
 emisor_name text not null check(length(btrim(emisor_name)) between 3 and 100),
 received_issued_at timestamptz not null,
 received_total_cents bigint not null check(received_total_cents between 0 and 10000000000),
 received_tax_cents bigint not null check(received_tax_cents between 0 and 10000000000),
 message_code text not null check(message_code in('1','2','3')),
 doc_type text not null check(doc_type in('05','06','07')),
 detail text check(detail is null or length(detail) between 5 and 160),
 tax_condition text check(tax_condition is null or tax_condition in('01','02','03','04','05')),
 credit_tax_cents bigint check(credit_tax_cents is null or credit_tax_cents>=0),
 expense_cents bigint check(expense_cents is null or expense_cents>=0),
 activity_code text not null check(activity_code ~ '^[0-9]{6}$'),
 consecutivo text not null check(consecutivo ~ '^[0-9]{3}[0-9]{5}(05|06|07)[0-9]{10}$'),
 mode text not null check(mode in('mock','sandbox','production')),
 provider text not null default 'mock' check(provider in('mock','hacienda-sandbox','gti')),
 status text not null default 'borrador' check(status in('borrador','firmado','enviado','recibido','procesando','aceptado','rechazado','error')),
 xml text,xml_sha256 text check(xml_sha256 is null or xml_sha256 ~ '^[a-f0-9]{64}$'),
 signed_xml text,signed_sha256 text check(signed_sha256 is null or signed_sha256 ~ '^[a-f0-9]{64}$'),
 signer text check(signer is null or signer in('mock','p12')),
 response_xml text,response_code integer check(response_code is null or response_code in(1,2,3)),
 response_message text check(response_message is null or length(response_message)<=2000),
 attempts integer not null default 0 check(attempts between 0 and 100),
 next_attempt_at timestamptz,last_error text check(last_error is null or length(last_error)<=300),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,consecutivo),
 check(doc_type=case message_code when '1' then '05' when '2' then '06' else '07' end),
 check(message_code='1' or detail is not null),
 check(message_code<>'2' or credit_tax_cents is not null and credit_tax_cents<=received_tax_cents),
 check(substr(consecutivo,9,2)=doc_type),
 check(status='borrador' or xml is not null and signed_xml is not null and xml_sha256 is not null and signed_sha256 is not null and signer is not null),
 check(status not in('aceptado','rechazado') or response_code is not null)
);
-- One live answer per received document (a rejected answer frees it).
create unique index if not exists pro_einvoice_receiver_one_live on public.pro_einvoice_receiver_messages(owner_id,received_clave) where status<>'rechazado';
create index if not exists pro_einvoice_receiver_recent on public.pro_einvoice_receiver_messages(owner_id,created_at desc);
create table if not exists public.pro_einvoice_receiver_events(
 owner_id uuid not null,message_id uuid not null,id bigint generated always as identity,
 from_status text,to_status text not null,detail jsonb not null default '{}',created_at timestamptz not null default now(),
 primary key(owner_id,message_id,id),foreign key(owner_id,message_id) references public.pro_einvoice_receiver_messages(owner_id,id) on delete cascade
);
create table if not exists public.pro_einvoice_provider_responses(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id bigint generated always as identity,
 document_id uuid,receiver_message_id uuid,
 provider text not null check(provider in('mock','hacienda-sandbox','gti')),
 mode text not null check(mode in('mock','sandbox','production')),
 operation text not null check(operation in('issue','status','receiver_message','receiver_status')),
 attempt integer not null check(attempt between 1 and 100),
 http_status integer check(http_status is null or http_status between 0 and 599),
 outcome text not null check(outcome in('received','duplicate','error','timeout','state')),
 state text check(state is null or state in('recibido','procesando','aceptado','rechazado','error')),
 message text check(message is null or length(message)<=500),
 body_sha256 text check(body_sha256 is null or body_sha256 ~ '^[a-f0-9]{64}$'),
 created_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,document_id) references public.pro_einvoice_documents(owner_id,id) on delete cascade,
 foreign key(owner_id,receiver_message_id) references public.pro_einvoice_receiver_messages(owner_id,id) on delete cascade,
 check((document_id is null)<>(receiver_message_id is null)),
 check((outcome='state')=(state is not null)),
 check((operation in('issue','status'))=(document_id is not null))
);
create index if not exists pro_einvoice_provider_responses_document on public.pro_einvoice_provider_responses(owner_id,document_id,id) where document_id is not null;
create index if not exists pro_einvoice_provider_responses_receiver on public.pro_einvoice_provider_responses(owner_id,receiver_message_id,id) where receiver_message_id is not null;
drop trigger if exists pro_einvoice_provider_responses_immutable on public.pro_einvoice_provider_responses;
create trigger pro_einvoice_provider_responses_immutable before update on public.pro_einvoice_provider_responses for each row execute function public.pro_einvoice_immutable();
drop trigger if exists pro_einvoice_receiver_events_immutable on public.pro_einvoice_receiver_events;
create trigger pro_einvoice_receiver_events_immutable before update on public.pro_einvoice_receiver_events for each row execute function public.pro_einvoice_immutable();

-- 4) State machine with «procesando» (replaces the Round 6A guard; same freeze rules + provider frozen).
--   borrador→firmado · firmado→enviado|error · enviado→recibido|procesando|aceptado|rechazado|error
--   recibido→procesando|aceptado|rechazado|error · procesando→aceptado|rechazado|error
--   error→enviado|recibido|procesando|aceptado|rechazado · aceptado/rechazado final.
create or replace function public.pro_einvoice_transition_ok(p_from text,p_to text) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select p_from=p_to or p_from='borrador' and p_to='firmado' or p_from='firmado' and p_to in('enviado','error')
  or p_from='enviado' and p_to in('recibido','procesando','aceptado','rechazado','error') or p_from='recibido' and p_to in('procesando','aceptado','rechazado','error')
  or p_from='procesando' and p_to in('aceptado','rechazado','error') or p_from='error' and p_to in('enviado','recibido','procesando','aceptado','rechazado') $$;
create or replace function public.pro_einvoice_document_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.status in('aceptado','rechazado') then raise exception 'Emitted document is final and immutable' using errcode='23514';end if;
 if not public.pro_einvoice_transition_ok(old.status,new.status) then
  raise exception 'Invalid electronic invoice transition % → %',old.status,new.status using errcode='23514';
 end if;
 if new.owner_id<>old.owner_id or new.id<>old.id or new.draft_id<>old.draft_id or new.doc_type<>old.doc_type or new.mode<>old.mode or new.provider<>old.provider or new.clave<>old.clave or new.consecutivo<>old.consecutivo
  or new.issued_at<>old.issued_at or new.total_cents<>old.total_cents or new.tax_cents<>old.tax_cents or new.snapshot<>old.snapshot
  or new.reference_document_id is distinct from old.reference_document_id or new.reference_code is distinct from old.reference_code or new.reference_reason is distinct from old.reference_reason
  or new.receiver_name is distinct from old.receiver_name or new.receiver_id is distinct from old.receiver_id or new.receiver_id_type is distinct from old.receiver_id_type or new.created_at<>old.created_at then
  raise exception 'Electronic invoice identity is immutable' using errcode='23514';
 end if;
 if old.status<>'borrador' and (new.xml is distinct from old.xml or new.signed_xml is distinct from old.signed_xml or new.xml_sha256 is distinct from old.xml_sha256 or new.signed_sha256 is distinct from old.signed_sha256 or new.signer is distinct from old.signer) then
  raise exception 'Signed XML is immutable' using errcode='23514';
 end if;
 if new.status='firmado' and old.status='borrador' and (encode(sha256(convert_to(new.xml,'UTF8')),'hex')<>new.xml_sha256 or encode(sha256(convert_to(new.signed_xml,'UTF8')),'hex')<>new.signed_sha256 or position(new.clave in new.xml)=0 or position(new.consecutivo in new.xml)=0) then
  raise exception 'Signed XML does not match its digest or clave' using errcode='22023',hint='pro_einvoice_xml_mismatch';
 end if;
 new.updated_at:=now();
 return new;
end $$;
create or replace function public.pro_einvoice_receiver_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.status in('aceptado','rechazado') then raise exception 'Receiver message is final and immutable' using errcode='23514';end if;
 if not public.pro_einvoice_transition_ok(old.status,new.status) then raise exception 'Invalid receiver message transition % → %',old.status,new.status using errcode='23514';end if;
 if (to_jsonb(new)-array['status','xml','xml_sha256','signed_xml','signed_sha256','signer','response_xml','response_code','response_message','attempts','next_attempt_at','last_error','updated_at'])
   <>(to_jsonb(old)-array['status','xml','xml_sha256','signed_xml','signed_sha256','signer','response_xml','response_code','response_message','attempts','next_attempt_at','last_error','updated_at']) then
  raise exception 'Receiver message identity is immutable' using errcode='23514';
 end if;
 if old.status<>'borrador' and (new.xml is distinct from old.xml or new.signed_xml is distinct from old.signed_xml or new.xml_sha256 is distinct from old.xml_sha256 or new.signed_sha256 is distinct from old.signed_sha256 or new.signer is distinct from old.signer) then
  raise exception 'Signed XML is immutable' using errcode='23514';
 end if;
 if new.status='firmado' and old.status='borrador' and (encode(sha256(convert_to(new.xml,'UTF8')),'hex')<>new.xml_sha256 or encode(sha256(convert_to(new.signed_xml,'UTF8')),'hex')<>new.signed_sha256 or position(new.received_clave in new.xml)=0 or position(new.consecutivo in new.xml)=0) then
  raise exception 'Signed XML does not match its digest or clave' using errcode='22023',hint='pro_einvoice_xml_mismatch';
 end if;
 new.updated_at:=now();
 return new;
end $$;
drop trigger if exists pro_einvoice_receiver_guard on public.pro_einvoice_receiver_messages;
create trigger pro_einvoice_receiver_guard before update on public.pro_einvoice_receiver_messages for each row execute function public.pro_einvoice_receiver_guard();
create or replace function public.pro_einvoice_receiver_event() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='INSERT' or new.status<>old.status then
  insert into public.pro_einvoice_receiver_events(owner_id,message_id,from_status,to_status,detail) values(new.owner_id,new.id,case when tg_op='INSERT' then null else old.status end,new.status,
   jsonb_strip_nulls(jsonb_build_object('attempts',new.attempts,'error',case when new.status='error' then new.last_error end,'responseCode',new.response_code)));
 end if;
 return null;
end $$;
drop trigger if exists pro_einvoice_receiver_event on public.pro_einvoice_receiver_messages;
create trigger pro_einvoice_receiver_event after insert or update on public.pro_einvoice_receiver_messages for each row execute function public.pro_einvoice_receiver_event();

-- 5) JSON (adds provider and the provider responses; same keys as Round 6A otherwise).
create or replace function public.pro_einvoice_settings_json(p_row public.pro_einvoice_settings) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_row.owner_id is null then null else jsonb_build_object('idType',p_row.id_type,'idNumber',p_row.id_number,'name',p_row.name,'commercialName',coalesce(p_row.commercial_name,''),
  'activityCode',p_row.activity_code,'province',p_row.province,'canton',p_row.canton,'district',p_row.district,'barrio',coalesce(p_row.barrio,''),'otherSigns',p_row.other_signs,
  'phone',coalesce(p_row.phone,''),'email',p_row.email,'branch',p_row.branch,'terminal',p_row.terminal,'providerSystems',p_row.provider_systems,'provider',p_row.provider) end $$;
-- Last 30 adapter calls of one document or receiver message, oldest first.
create or replace function public.pro_einvoice_responses_json(p_owner uuid,p_document uuid,p_message uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('provider',q.provider,'mode',q.mode,'operation',q.operation,'attempt',q.attempt,'httpStatus',q.http_status,'outcome',q.outcome,'state',q.state,'message',q.message,'at',q.created_at) order by q.id),'[]')
 from (select r.* from public.pro_einvoice_provider_responses r where r.owner_id=p_owner and (p_document is not null and r.document_id=p_document or p_message is not null and r.receiver_message_id=p_message) order by r.id desc limit 30) q $$;
create or replace function public.pro_einvoice_document_json(p_doc public.pro_einvoice_documents,p_full boolean default false) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_doc.id,'draftId',p_doc.draft_id,'docType',p_doc.doc_type,'mode',p_doc.mode,'provider',p_doc.provider,'clave',p_doc.clave,'consecutivo',p_doc.consecutivo,'issuedAt',p_doc.issued_at,
  'status',p_doc.status,'responseCode',p_doc.response_code,'responseMessage',p_doc.response_message,'totalCents',p_doc.total_cents,'taxCents',p_doc.tax_cents,
  'receiverName',p_doc.receiver_name,'referenceDocumentId',p_doc.reference_document_id,'referenceCode',p_doc.reference_code,'referenceReason',p_doc.reference_reason,
  'attempts',p_doc.attempts,'nextAttemptAt',p_doc.next_attempt_at,'lastError',p_doc.last_error,'signer',p_doc.signer,'hasXml',p_doc.signed_xml is not null,'hasResponse',p_doc.response_xml is not null,
  'xmlSha256',p_doc.signed_sha256,'createdAt',p_doc.created_at,'updatedAt',p_doc.updated_at,
  'events',coalesce((select jsonb_agg(jsonb_build_object('from',e.from_status,'to',e.to_status,'detail',e.detail,'at',e.created_at) order by e.id) from public.pro_einvoice_events e where e.owner_id=p_doc.owner_id and e.document_id=p_doc.id),'[]'),
  'responses',public.pro_einvoice_responses_json(p_doc.owner_id,p_doc.id,null))
  ||case when p_full then jsonb_build_object('xml',p_doc.xml,'signedXml',p_doc.signed_xml,'responseXml',p_doc.response_xml,'snapshot',p_doc.snapshot) else '{}'::jsonb end $$;
create or replace function public.pro_einvoice_receiver_json(m public.pro_einvoice_receiver_messages,p_full boolean default false) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',m.id,'receivedClave',m.received_clave,'emisorIdType',m.emisor_id_type,'emisorId',m.emisor_id,'emisorName',m.emisor_name,'receivedIssuedAt',m.received_issued_at,
  'receivedTotalCents',m.received_total_cents,'receivedTaxCents',m.received_tax_cents,'messageCode',m.message_code,'docType',m.doc_type,'detail',m.detail,'taxCondition',m.tax_condition,
  'creditTaxCents',m.credit_tax_cents,'expenseCents',m.expense_cents,'activityCode',m.activity_code,'consecutivo',m.consecutivo,'mode',m.mode,'provider',m.provider,'status',m.status,
  'responseCode',m.response_code,'responseMessage',m.response_message,'attempts',m.attempts,'nextAttemptAt',m.next_attempt_at,'lastError',m.last_error,'hasXml',m.signed_xml is not null,'hasResponse',m.response_xml is not null,
  'createdAt',m.created_at,'updatedAt',m.updated_at,
  'events',coalesce((select jsonb_agg(jsonb_build_object('from',e.from_status,'to',e.to_status,'detail',e.detail,'at',e.created_at) order by e.id) from public.pro_einvoice_receiver_events e where e.owner_id=m.owner_id and e.message_id=m.id),'[]'),
  'responses',public.pro_einvoice_responses_json(m.owner_id,null,m.id))
  ||case when p_full then jsonb_build_object('xml',m.xml,'signedXml',m.signed_xml,'responseXml',m.response_xml) else '{}'::jsonb end $$;

-- Owner read for one draft (Round 6A shape); «credited» now counts credit notes only (a debit note adds, never credits).
create or replace function public.pro_einvoice_read(p_actor uuid,p_draft uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare s public.pro_einvoice_settings;d public.pro_invoice_drafts;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into s from public.pro_einvoice_settings where owner_id=p_actor;
 if p_draft is null then return jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',coalesce(s.revision,0));end if;
 select * into d from public.pro_invoice_drafts where user_id=p_actor and id=p_draft;
 if not found then return null;end if;
 return jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',coalesce(s.revision,0),'draftRevision',d.revision,'draftTotalCents',d.total_cents,
  'documents',coalesce((select jsonb_agg(public.pro_einvoice_document_json(x) order by x.created_at desc,x.consecutivo desc) from public.pro_einvoice_documents x where x.owner_id=p_actor and x.draft_id=d.id),'[]'),
  'credited',coalesce((select jsonb_object_agg(o.id,(select coalesce(sum(n.total_cents),0) from public.pro_einvoice_documents n where n.owner_id=p_actor and n.reference_document_id=o.id and n.doc_type='03' and n.status<>'rechazado')) from public.pro_einvoice_documents o where o.owner_id=p_actor and o.draft_id=d.id and o.doc_type in('01','04')),'{}'),
  'debited',coalesce((select jsonb_object_agg(o.id,(select coalesce(sum(n.total_cents),0) from public.pro_einvoice_documents n where n.owner_id=p_actor and n.reference_document_id=o.id and n.doc_type='02' and n.status<>'rechazado')) from public.pro_einvoice_documents o where o.owner_id=p_actor and o.draft_id=d.id and o.doc_type in('01','04')),'{}'));
end $$;

-- Records one adapter call (inside the same transaction as the state change it caused).
create or replace function public.pro_einvoice_record_response(p_actor uuid,p_document uuid,p_message uuid,p_response jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if p_response is null or jsonb_typeof(p_response)<>'object' then return;end if;
 if jsonb_typeof(p_response->'attempt')<>'number' or (p_response->'httpStatus' is not null and jsonb_typeof(p_response->'httpStatus') not in('number','null')) then raise exception 'Invalid provider response' using errcode='22023';end if;
 insert into public.pro_einvoice_provider_responses(owner_id,document_id,receiver_message_id,provider,mode,operation,attempt,http_status,outcome,state,message,body_sha256)
 values(p_actor,p_document,p_message,p_response->>'provider',p_response->>'mode',p_response->>'operation',(p_response->>'attempt')::integer,(p_response->>'httpStatus')::integer,p_response->>'outcome',
  nullif(p_response->>'state',''),left(p_response->>'message',500),nullif(p_response->>'bodySha256',''));
end $$;

-- 6) Mutations for emitted documents (replaces the Round 6A function: + debit note, + procesando, + duplicate,
--    + provider and responses). Same receipts, lock, CAS and hints.
create or replace function public.pro_einvoice_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_einvoice_actions;h text:=md5(p_input::text);s public.pro_einvoice_settings;d public.pro_invoice_drafts;x public.pro_einvoice_documents;
 o public.pro_einvoice_documents;dtype text;num bigint;cons text;clave text;issued timestamptz;sec text;result jsonb;st text;credited bigint;prov text;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' then raise exception 'Invalid input' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-einvoice:'||p_actor::text,0));
 select * into receipt from public.pro_einvoice_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input_hash<>h then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;

 if act='save_settings' then
  select * into s from public.pro_einvoice_settings where owner_id=p_actor for update;
  if jsonb_typeof(p_input->'revision')<>'number' or (p_input->>'revision')::integer<>coalesce(s.revision,0) then raise exception 'Settings changed' using errcode='40001';end if;
  prov:=coalesce(nullif(p_input#>>'{settings,provider}',''),s.provider,'mock');
  insert into public.pro_einvoice_settings(owner_id,id_type,id_number,name,commercial_name,activity_code,province,canton,district,barrio,other_signs,phone,email,branch,terminal,provider_systems,provider,revision)
  values(p_actor,p_input#>>'{settings,idType}',p_input#>>'{settings,idNumber}',p_input#>>'{settings,name}',nullif(p_input#>>'{settings,commercialName}',''),p_input#>>'{settings,activityCode}',
   p_input#>>'{settings,province}',p_input#>>'{settings,canton}',p_input#>>'{settings,district}',nullif(p_input#>>'{settings,barrio}',''),p_input#>>'{settings,otherSigns}',nullif(p_input#>>'{settings,phone}',''),
   p_input#>>'{settings,email}',coalesce(p_input#>>'{settings,branch}','001'),coalesce(p_input#>>'{settings,terminal}','00001'),p_input#>>'{settings,providerSystems}',prov,1)
  on conflict(owner_id) do update set id_type=excluded.id_type,id_number=excluded.id_number,name=excluded.name,commercial_name=excluded.commercial_name,activity_code=excluded.activity_code,
   province=excluded.province,canton=excluded.canton,district=excluded.district,barrio=excluded.barrio,other_signs=excluded.other_signs,phone=excluded.phone,email=excluded.email,
   branch=excluded.branch,terminal=excluded.terminal,provider_systems=excluded.provider_systems,provider=excluded.provider,revision=pro_einvoice_settings.revision+1,updated_at=now()
  returning * into s;
  result:=jsonb_build_object('settings',public.pro_einvoice_settings_json(s),'settingsRevision',s.revision);

 elsif act='reserve' then
  dtype:=p_input->>'docType';
  if dtype not in('01','02','03','04') or p_input->>'mode' not in('mock','sandbox','production') or p_input->>'securityCode' !~ '^[0-9]{8}$' or jsonb_typeof(p_input->'snapshot')<>'object'
   or coalesce(p_input->>'provider','mock') not in('mock','hacienda-sandbox','gti') or (p_input->>'mode'='mock')<>(coalesce(p_input->>'provider','mock')='mock') then raise exception 'Invalid reservation' using errcode='22023';end if;
  select * into s from public.pro_einvoice_settings where owner_id=p_actor;
  if not found then raise exception 'Emisor settings missing' using errcode='22023',hint='pro_einvoice_settings';end if;
  if jsonb_typeof(p_input->'settingsRevision')<>'number' or (p_input->>'settingsRevision')::integer<>s.revision then raise exception 'Settings changed' using errcode='40001';end if;
  select * into d from public.pro_invoice_drafts where user_id=p_actor and id=(p_input->>'draftId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if jsonb_typeof(p_input->'draftRevision')<>'number' or (p_input->>'draftRevision')::integer<>d.revision then raise exception 'Draft changed' using errcode='40001';end if;
  if exists(select 1 from public.pro_invoice_draft_management m where m.user_id=p_actor and m.draft_id=d.id and m.archived) then raise exception 'Archived draft' using errcode='22023',hint='pro_einvoice_archived';end if;
  if jsonb_typeof(p_input->'totalCents')<>'number' or jsonb_typeof(p_input->'taxCents')<>'number' then raise exception 'Invalid totals' using errcode='22023';end if;
  if dtype in('01','04') then
   if exists(select 1 from public.pro_einvoice_documents where owner_id=p_actor and draft_id=d.id and doc_type in('01','04') and status<>'rechazado') then raise exception 'Draft already emitted' using errcode='40001',hint='pro_einvoice_emitted';end if;
   if (p_input->>'totalCents')::bigint<>d.total_cents then raise exception 'Totals do not match the draft' using errcode='22023',hint='pro_einvoice_totals';end if;
  else
   select * into o from public.pro_einvoice_documents where owner_id=p_actor and id=(p_input->>'referenceDocumentId')::uuid and draft_id=d.id and doc_type in('01','04');
   if not found then raise exception 'Unknown original' using errcode='22023',hint='pro_einvoice_reference';end if;
   if o.status<>'aceptado' then raise exception 'Original not accepted' using errcode='22023',hint='pro_einvoice_reference_state';end if;
   if length(btrim(coalesce(p_input->>'referenceReason','')))<5 then raise exception 'Invalid reference' using errcode='22023';end if;
   if dtype='03' then
    if p_input->>'referenceCode' not in('01','02') then raise exception 'Invalid reference' using errcode='22023';end if;
    select coalesce(sum(total_cents),0) into credited from public.pro_einvoice_documents where owner_id=p_actor and reference_document_id=o.id and doc_type='03' and status<>'rechazado';
    if (p_input->>'totalCents')::bigint<1 or (p_input->>'totalCents')::bigint>o.total_cents-credited then raise exception 'Credit exceeds original' using errcode='22023',hint='pro_einvoice_credit_exceeds';end if;
    if p_input->>'referenceCode'='01' and (credited>0 or (p_input->>'totalCents')::bigint<>o.total_cents) then raise exception 'Full cancellation must credit the whole original' using errcode='22023',hint='pro_einvoice_credit_exceeds';end if;
   else
    -- Debit note: adds to the original (code 02 «Corrige monto»); never on a fully cancelled original.
    if p_input->>'referenceCode'<>'02' then raise exception 'Invalid reference' using errcode='22023';end if;
    if (p_input->>'totalCents')::bigint<1 then raise exception 'Invalid debit' using errcode='22023',hint='pro_einvoice_debit_amount';end if;
    if exists(select 1 from public.pro_einvoice_documents n where n.owner_id=p_actor and n.reference_document_id=o.id and n.doc_type='03' and n.reference_code='01' and n.status<>'rechazado') then
     raise exception 'Original was cancelled' using errcode='22023',hint='pro_einvoice_reference_cancelled';end if;
   end if;
  end if;
  insert into public.pro_einvoice_sequences(owner_id,branch,terminal,doc_type) values(p_actor,s.branch,s.terminal,dtype) on conflict do nothing;
  update public.pro_einvoice_sequences set last_number=case when last_number>=9999999999 then 1 else last_number+1 end where owner_id=p_actor and branch=s.branch and terminal=s.terminal and doc_type=dtype returning last_number into num;
  cons:=s.branch||s.terminal||dtype||lpad(num::text,10,'0');
  issued:=date_trunc('second',now());
  sec:=p_input->>'securityCode';
  clave:='506'||to_char(issued at time zone 'America/Costa_Rica','DDMMYY')||lpad(s.id_number,12,'0')||cons||'1'||sec;
  insert into public.pro_einvoice_documents(owner_id,id,draft_id,doc_type,mode,provider,clave,consecutivo,issued_at,total_cents,tax_cents,receiver_name,receiver_id_type,receiver_id,reference_document_id,reference_code,reference_reason,snapshot)
  values(p_actor,aid,d.id,dtype,p_input->>'mode',coalesce(p_input->>'provider','mock'),clave,cons,issued,(p_input->>'totalCents')::bigint,(p_input->>'taxCents')::bigint,nullif(p_input->>'receiverName',''),nullif(p_input->>'receiverIdType',''),nullif(p_input->>'receiverId',''),
   case when dtype in('02','03') then o.id end,case when dtype in('02','03') then p_input->>'referenceCode' end,case when dtype in('02','03') then btrim(p_input->>'referenceReason') end,p_input->'snapshot') returning * into x;
  result:=public.pro_einvoice_document_json(x)||jsonb_build_object('settings',public.pro_einvoice_settings_json(s));

 elsif act in('sign','submitted','status') then
  select * into x from public.pro_einvoice_documents where owner_id=p_actor and id=(p_input->>'documentId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if act='sign' then
   if x.status<>'borrador' then raise exception 'Already signed' using errcode='40001';end if;
   if p_input->>'signer' not in('mock','p12') then raise exception 'Invalid signer' using errcode='22023';end if;
   if x.mode='mock' and p_input->>'signer'<>'mock' or x.mode<>'mock' and p_input->>'signer'<>'p12' then raise exception 'Signer does not match the mode' using errcode='22023';end if;
   update public.pro_einvoice_documents set status='firmado',xml=p_input->>'xml',xml_sha256=p_input->>'xmlSha256',signed_xml=p_input->>'signedXml',signed_sha256=p_input->>'signedSha256',signer=p_input->>'signer'
   where owner_id=p_actor and id=x.id returning * into x;
  elsif act='submitted' then
   if x.status not in('firmado','error') then raise exception 'Not ready to send' using errcode='40001';end if;
   if p_input->>'outcome' in('sent','duplicate') then
    update public.pro_einvoice_documents set status='enviado',attempts=attempts+1,next_attempt_at=null,last_error=null,response_message=coalesce(left(p_input->>'message',2000),response_message) where owner_id=p_actor and id=x.id returning * into x;
   elsif p_input->>'outcome'='error' then
    update public.pro_einvoice_documents set status='error',attempts=attempts+1,next_attempt_at=now()+public.pro_integration_retry_delay(attempts+1),last_error=left(coalesce(p_input->>'message','Error'),300) where owner_id=p_actor and id=x.id returning * into x;
   else raise exception 'Invalid outcome' using errcode='22023';end if;
   perform public.pro_einvoice_record_response(p_actor,x.id,null,p_input->'response');
  else
   st:=p_input->>'state';
   if st not in('recibido','procesando','aceptado','rechazado','error') then raise exception 'Invalid state' using errcode='22023';end if;
   if x.status not in('enviado','recibido','procesando','error') then raise exception 'Not sent' using errcode='40001';end if;
   if st in('aceptado','rechazado') and (p_input->>'responseXml' is null or (p_input->>'responseCode')::integer not in(1,2,3)) then raise exception 'Final state needs the response' using errcode='22023';end if;
   if st<>x.status then
    update public.pro_einvoice_documents set status=st,response_xml=case when st in('aceptado','rechazado') then p_input->>'responseXml' else response_xml end,
     response_code=case when st in('aceptado','rechazado') then (p_input->>'responseCode')::integer else response_code end,
     response_message=coalesce(left(p_input->>'message',2000),response_message),
     attempts=case when st='error' then attempts+1 else attempts end,
     next_attempt_at=case when st='error' then now()+public.pro_integration_retry_delay(attempts+1) else null end,
     last_error=case when st='error' then left(coalesce(p_input->>'message','Error'),300) else null end
    where owner_id=p_actor and id=x.id returning * into x;
   end if;
   perform public.pro_einvoice_record_response(p_actor,x.id,null,p_input->'response');
  end if;
  result:=public.pro_einvoice_document_json(x);
 else raise exception 'Invalid electronic invoice action' using errcode='22023';end if;
 insert into public.pro_einvoice_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,h,result);
 return result;
exception when check_violation then
 if sqlerrm like '%immutable%' or sqlerrm like '%transition%' or sqlerrm like '%final%' then raise;end if;
 raise exception 'Invalid electronic invoice data: %',sqlerrm using errcode='22023',hint='pro_einvoice_invalid';
end $$;

-- 7) Receiver messages: reserve (gapless 05/06/07), sign, submitted, status. Same receipts table and lock.
create or replace function public.pro_einvoice_receiver_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_einvoice_actions;h text:=md5(p_input::text);s public.pro_einvoice_settings;m public.pro_einvoice_receiver_messages;
 code text;dtype text;num bigint;result jsonb;st text;issued timestamptz;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' then raise exception 'Invalid input' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-einvoice:'||p_actor::text,0));
 select * into receipt from public.pro_einvoice_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input_hash<>h then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 if act='reserve' then
  code:=p_input->>'messageCode';
  if code not in('1','2','3') or p_input->>'mode' not in('mock','sandbox','production') or coalesce(p_input->>'provider','mock') not in('mock','hacienda-sandbox','gti')
   or (p_input->>'mode'='mock')<>(coalesce(p_input->>'provider','mock')='mock') then raise exception 'Invalid receiver message' using errcode='22023';end if;
  begin issued:=(p_input->>'receivedIssuedAt')::timestamptz;exception when others then raise exception 'Invalid issue date' using errcode='22023';end;
  if issued is null or issued>now()+interval '1 day' then raise exception 'Invalid issue date' using errcode='22023';end if;
  select * into s from public.pro_einvoice_settings where owner_id=p_actor;
  if not found then raise exception 'Emisor settings missing' using errcode='22023',hint='pro_einvoice_settings';end if;
  if exists(select 1 from public.pro_einvoice_receiver_messages where owner_id=p_actor and received_clave=p_input->>'receivedClave' and status<>'rechazado') then
   raise exception 'Already answered' using errcode='40001',hint='pro_einvoice_receiver_answered';end if;
  -- The received clave carries the supplier id (positions 10–21, left-padded): it must match the declared emisor.
  if substr(p_input->>'receivedClave',10,12)<>lpad(coalesce(p_input->>'emisorId',''),12,'0') then raise exception 'Clave does not match the supplier' using errcode='22023',hint='pro_einvoice_receiver_clave';end if;
  if lpad(coalesce(p_input->>'emisorId',''),12,'0')=lpad(s.id_number,12,'0') then raise exception 'Own document' using errcode='22023',hint='pro_einvoice_receiver_own';end if;
  dtype:=case code when '1' then '05' when '2' then '06' else '07' end;
  insert into public.pro_einvoice_sequences(owner_id,branch,terminal,doc_type) values(p_actor,s.branch,s.terminal,dtype) on conflict do nothing;
  update public.pro_einvoice_sequences set last_number=case when last_number>=9999999999 then 1 else last_number+1 end where owner_id=p_actor and branch=s.branch and terminal=s.terminal and doc_type=dtype returning last_number into num;
  insert into public.pro_einvoice_receiver_messages(owner_id,id,received_clave,emisor_id_type,emisor_id,emisor_name,received_issued_at,received_total_cents,received_tax_cents,message_code,doc_type,detail,tax_condition,credit_tax_cents,expense_cents,activity_code,consecutivo,mode,provider)
  values(p_actor,aid,p_input->>'receivedClave',p_input->>'emisorIdType',p_input->>'emisorId',btrim(p_input->>'emisorName'),issued,(p_input->>'receivedTotalCents')::bigint,(p_input->>'receivedTaxCents')::bigint,code,dtype,
   nullif(btrim(coalesce(p_input->>'detail','')),''),nullif(p_input->>'taxCondition',''),(p_input->>'creditTaxCents')::bigint,(p_input->>'expenseCents')::bigint,coalesce(nullif(p_input->>'activityCode',''),s.activity_code),
   s.branch||s.terminal||dtype||lpad(num::text,10,'0'),p_input->>'mode',coalesce(p_input->>'provider','mock')) returning * into m;
 elsif act in('sign','submitted','status') then
  select * into m from public.pro_einvoice_receiver_messages where owner_id=p_actor and id=(p_input->>'messageId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if act='sign' then
   if m.status<>'borrador' then raise exception 'Already signed' using errcode='40001';end if;
   if m.mode='mock' and p_input->>'signer'<>'mock' or m.mode<>'mock' and p_input->>'signer'<>'p12' then raise exception 'Signer does not match the mode' using errcode='22023';end if;
   update public.pro_einvoice_receiver_messages set status='firmado',xml=p_input->>'xml',xml_sha256=p_input->>'xmlSha256',signed_xml=p_input->>'signedXml',signed_sha256=p_input->>'signedSha256',signer=p_input->>'signer'
   where owner_id=p_actor and id=m.id returning * into m;
  elsif act='submitted' then
   if m.status not in('firmado','error') then raise exception 'Not ready to send' using errcode='40001';end if;
   if p_input->>'outcome' in('sent','duplicate') then
    update public.pro_einvoice_receiver_messages set status='enviado',attempts=attempts+1,next_attempt_at=null,last_error=null,response_message=coalesce(left(p_input->>'message',2000),response_message) where owner_id=p_actor and id=m.id returning * into m;
   elsif p_input->>'outcome'='error' then
    update public.pro_einvoice_receiver_messages set status='error',attempts=attempts+1,next_attempt_at=now()+public.pro_integration_retry_delay(attempts+1),last_error=left(coalesce(p_input->>'message','Error'),300) where owner_id=p_actor and id=m.id returning * into m;
   else raise exception 'Invalid outcome' using errcode='22023';end if;
   perform public.pro_einvoice_record_response(p_actor,null,m.id,p_input->'response');
  else
   st:=p_input->>'state';
   if st not in('recibido','procesando','aceptado','rechazado','error') then raise exception 'Invalid state' using errcode='22023';end if;
   if m.status not in('enviado','recibido','procesando','error') then raise exception 'Not sent' using errcode='40001';end if;
   if st in('aceptado','rechazado') and (p_input->>'responseXml' is null or (p_input->>'responseCode')::integer not in(1,2,3)) then raise exception 'Final state needs the response' using errcode='22023';end if;
   if st<>m.status then
    update public.pro_einvoice_receiver_messages set status=st,response_xml=case when st in('aceptado','rechazado') then p_input->>'responseXml' else response_xml end,
     response_code=case when st in('aceptado','rechazado') then (p_input->>'responseCode')::integer else response_code end,response_message=coalesce(left(p_input->>'message',2000),response_message),
     attempts=case when st='error' then attempts+1 else attempts end,next_attempt_at=case when st='error' then now()+public.pro_integration_retry_delay(attempts+1) else null end,
     last_error=case when st='error' then left(coalesce(p_input->>'message','Error'),300) else null end
    where owner_id=p_actor and id=m.id returning * into m;
   end if;
   perform public.pro_einvoice_record_response(p_actor,null,m.id,p_input->'response');
  end if;
 else raise exception 'Invalid receiver message action' using errcode='22023';end if;
 result:=public.pro_einvoice_receiver_json(m);
 insert into public.pro_einvoice_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,h,result);
 return result;
exception when check_violation then
 if sqlerrm like '%immutable%' or sqlerrm like '%transition%' or sqlerrm like '%final%' then raise;end if;
 raise exception 'Invalid receiver message data: %',sqlerrm using errcode='22023',hint='pro_einvoice_invalid';
end $$;
create or replace function public.pro_einvoice_receiver_read(p_actor uuid,p_id uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare m public.pro_einvoice_receiver_messages;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_id is not null then
  select * into m from public.pro_einvoice_receiver_messages where owner_id=p_actor and id=p_id;
  if not found then return null;end if;
  return public.pro_einvoice_receiver_json(m,true);
 end if;
 return jsonb_build_object('messages',coalesce((select jsonb_agg(public.pro_einvoice_receiver_json(x) order by x.created_at desc) from public.pro_einvoice_receiver_messages x where x.owner_id=p_actor and x.created_at>=coalesce((select min(created_at) from (select created_at from public.pro_einvoice_receiver_messages where owner_id=p_actor order by created_at desc limit 100) z),'-infinity')),'[]'));
end $$;
-- Pending retries for the worker / «Reintentar pendientes» (due errors only, oldest first).
create or replace function public.pro_einvoice_due_retries(p_actor uuid,p_limit integer default 20) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('kind',k,'id',i,'attempts',a,'nextAttemptAt',n) order by n) from (
  select 'document' k,id i,attempts a,next_attempt_at n from public.pro_einvoice_documents where owner_id=p_actor and status='error' and next_attempt_at<=now()
  union all select 'receiver',id,attempts,next_attempt_at from public.pro_einvoice_receiver_messages where owner_id=p_actor and status='error' and next_attempt_at<=now()
  order by 4 limit least(greatest(coalesce(p_limit,20),1),100)) q),'[]');
end $$;

do $$declare n text;begin foreach n in array array['pro_einvoice_receiver_messages','pro_einvoice_receiver_events','pro_einvoice_provider_responses'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);
end loop;
 grant select,insert,update on public.pro_einvoice_receiver_messages to service_role;
 grant select,insert on public.pro_einvoice_receiver_events,public.pro_einvoice_provider_responses to service_role;
end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_einvoice\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text ~ '^pro_einvoice_(immutable|document_guard|document_event|draft_lock|receiver_guard|receiver_event)\(' then execute format('revoke all on function %s from service_role',f);
  else execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== online-payments-local.sql =====
-- LOCAL PRO ONLY. Round 6A (2026-11-13): online payments — payment links for an invoice draft or a
-- payment-plan installment, a hosted page in ContrataCR (/pagar#enlace=…), card and SINPE Móvil through
-- a processor ADAPTER (deterministic local mock by default; a sandbox skeleton activates only with env keys).
-- * A link stores only the SHA-256 of a random token (the token travels in the URL fragment). Amount is
--   fixed at creation: what is still due on the draft (total − applied − credit notes) or on the
--   installment, never above the job balance. One active link per invoice draft / installment.
-- * Attempts never store a card number or CVC (last 4 digits only) — state guarded by a trigger.
-- * The processor's webhook event (inbox of integrations-local.sql, idempotent by event id) creates the
--   ledger payment in pro_client_entries EXACTLY ONCE (deterministic ledger id from provider+event id,
--   unique (provider,event_id) and (attempt,kind) in pro_payment_transactions), through the existing
--   writers: pro_invoice_payment_mutate (invoice: ledger payment + application) or
--   pro_record_client_operation (installment: ledger payment the plan applies oldest-first).
-- * A refund creates the ledger REVERSAL (payment_void) exactly once; nothing is deleted.
-- * Anything that cannot be booked (balance changed, link no longer active, amount mismatch) is kept as
--   a reconciliation EXCEPTION for the owner (refund or record manually); money is never silently lost.
begin;

create table if not exists public.pro_payment_links(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,token_hash text not null unique check(token_hash ~ '^[a-f0-9]{64}$'),
 target text not null check(target in('invoice','installment')),
 draft_id uuid,plan_id uuid,plan_revision integer,installment_seq integer,
 work_id text not null,client_id text not null,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 currency text not null default 'CRC' check(currency='CRC'),
 description text not null check(length(description) between 1 and 160),
 provider text not null default 'tilopay' check(provider in('tilopay')),
 mode text not null check(mode in('mock','sandbox','production')),
 methods text[] not null check(cardinality(methods) between 1 and 2 and methods<@array['card','sinpe']),
 status text not null default 'active' check(status in('active','paid','cancelled')),
 expires_at timestamptz not null,
 created_at timestamptz not null default now(),paid_at timestamptz,cancelled_at timestamptz,
 cancel_reason text check(cancel_reason is null or length(cancel_reason) between 1 and 160),
 primary key(owner_id,id),
 foreign key(owner_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 check((target='invoice')=(draft_id is not null)),
 check((target='installment')=(plan_id is not null and plan_revision is not null and installment_seq is not null)),
 check((status='paid')=(paid_at is not null)),check((status='cancelled')=(cancelled_at is not null))
);
create unique index if not exists pro_payment_links_one_invoice on public.pro_payment_links(owner_id,draft_id) where status='active' and target='invoice';
create unique index if not exists pro_payment_links_one_installment on public.pro_payment_links(owner_id,plan_id,plan_revision,installment_seq) where status='active' and target='installment';
create index if not exists pro_payment_links_work on public.pro_payment_links(owner_id,work_id,created_at desc);
create table if not exists public.pro_payment_attempts(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,link_id uuid not null,provider text not null,mode text not null check(mode in('mock','sandbox','production')),
 processor_ref text not null check(length(processor_ref) between 4 and 80),
 method text not null check(method in('card','sinpe')),
 status text not null check(status in('pending','requires_action','succeeded','failed','refunded')),
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 card_last4 text check(card_last4 is null or card_last4 ~ '^[0-9]{4}$'),card_brand text check(card_brand is null or length(card_brand)<=20),
 sinpe_reference text check(sinpe_reference is null or sinpe_reference ~ '^[0-9]{8,25}$'),
 failure_code text check(failure_code is null or length(failure_code)<=60),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(provider,processor_ref),
 foreign key(owner_id,link_id) references public.pro_payment_links(owner_id,id) on delete cascade,
 check(method='card' or card_last4 is null),check(method='sinpe' or sinpe_reference is null)
);
create index if not exists pro_payment_attempts_link on public.pro_payment_attempts(owner_id,link_id,created_at desc);
create table if not exists public.pro_payment_transactions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,provider text not null,event_id text not null,kind text not null check(kind in('payment','refund')),
 attempt_id uuid not null,link_id uuid not null,entry_id uuid not null,invoice_payment_id uuid,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),created_at timestamptz not null default now(),
 primary key(owner_id,id),unique(provider,event_id),unique(owner_id,attempt_id,kind),
 foreign key(owner_id,attempt_id) references public.pro_payment_attempts(owner_id,id) on delete cascade,
 foreign key(owner_id,entry_id) references public.pro_client_entries(user_id,id) on delete cascade
);
create table if not exists public.pro_payment_refund_requests(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,transaction_id uuid not null,reason text not null check(length(reason) between 1 and 160),created_at timestamptz not null default now(),
 primary key(owner_id,action_id),unique(owner_id,transaction_id)
);
create table if not exists public.pro_payment_link_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input_hash text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);

create or replace function public.pro_payment_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Online payment transactions, refunds and receipts are immutable' using errcode='23514';end $$;
do $$declare n text;begin foreach n in array array['pro_payment_transactions','pro_payment_refund_requests','pro_payment_link_actions'] loop
 execute format('drop trigger if exists pro_payment_immutable on public.%I',n);
 execute format('create trigger pro_payment_immutable before update on public.%I for each row execute function public.pro_payment_immutable()',n);
end loop;end $$;
create or replace function public.pro_payment_link_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.status<>'active' then raise exception 'Payment link is final' using errcode='23514';end if;
 if (to_jsonb(new)-'status'-'paid_at'-'cancelled_at'-'cancel_reason')<>(to_jsonb(old)-'status'-'paid_at'-'cancelled_at'-'cancel_reason') then raise exception 'Payment link terms are immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_payment_link_guard on public.pro_payment_links;
create trigger pro_payment_link_guard before update on public.pro_payment_links for each row execute function public.pro_payment_link_guard();
create or replace function public.pro_payment_attempt_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-'status'-'failure_code'-'updated_at')<>(to_jsonb(old)-'status'-'failure_code'-'updated_at') then raise exception 'Payment attempt identity is immutable' using errcode='23514';end if;
 if new.status<>old.status and not(old.status='pending' and new.status in('requires_action','succeeded','failed') or old.status='requires_action' and new.status in('succeeded','failed') or old.status='succeeded' and new.status='refunded') then
  raise exception 'Invalid payment attempt transition % → %',old.status,new.status using errcode='23514';
 end if;
 new.updated_at:=now();return new;
end $$;
drop trigger if exists pro_payment_attempt_guard on public.pro_payment_attempts;
create trigger pro_payment_attempt_guard before update on public.pro_payment_attempts for each row execute function public.pro_payment_attempt_guard();

-- Deterministic RFC 4122 (version 4 layout) uuid from a text: ledger ids derived from provider + event id,
-- so a replayed event always maps to the same ledger row and every UUID validator accepts it.
create or replace function public.pro_payment_derived_uuid(p_text text) returns uuid
language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-'||substr('89ab',(get_byte(decode(substr(h,17,2),'hex'),0)%4)+1,1)||substr(h,18,3)||'-'||substr(h,21,12))::uuid from (select md5(p_text) h) x $$;
-- What can still be charged online for a draft (total − applied − credit notes, never above the job balance).
create or replace function public.pro_payment_link_due(p_owner uuid,p_draft uuid) returns bigint
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare d public.pro_invoice_drafts;acc jsonb;due bigint;
begin
 select * into d from public.pro_invoice_drafts where user_id=p_owner and id=p_draft;
 if not found or d.work_id is null then return 0;end if;
 due:=d.total_cents-public.pro_invoice_payment_used(p_owner,null,d.id)-public.pro_invoice_payment_credit_notes(p_owner,d.id);
 acc:=public.pro_work_account(p_owner,d.work_id);
 if acc->>'agreedCents' is null then return 0;end if;
 return greatest(least(due,(acc->>'balanceCents')::bigint),0);
end $$;

create or replace function public.pro_payment_link_json(p_link public.pro_payment_links) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_link.id,'target',p_link.target,'draftId',p_link.draft_id,'planId',p_link.plan_id,'planRevision',p_link.plan_revision,'seq',p_link.installment_seq,
  'workId',p_link.work_id,'amountCents',p_link.amount_cents,'currency',p_link.currency,'description',p_link.description,'provider',p_link.provider,'mode',p_link.mode,'methods',to_jsonb(p_link.methods),
  'status',case when p_link.status='active' and p_link.expires_at<=now() then 'expired' else p_link.status end,'expiresAt',p_link.expires_at,'createdAt',p_link.created_at,'paidAt',p_link.paid_at,
  'cancelledAt',p_link.cancelled_at,'cancelReason',p_link.cancel_reason,
  'attempts',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'method',a.method,'status',a.status,'amountCents',a.amount_cents,'cardLast4',a.card_last4,'cardBrand',a.card_brand,'sinpeReference',a.sinpe_reference,
    'failureCode',a.failure_code,'processorRef',a.processor_ref,'createdAt',a.created_at,
    'transactions',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'kind',t.kind,'entryId',t.entry_id,'amountCents',t.amount_cents,'at',t.created_at) order by t.created_at) from public.pro_payment_transactions t where t.owner_id=a.owner_id and t.attempt_id=a.id),'[]')) order by a.created_at desc)
   from public.pro_payment_attempts a where a.owner_id=p_link.owner_id and a.link_id=p_link.id),'[]')) $$;

create or replace function public.pro_payment_links_read(p_actor uuid,p_scope jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare draft uuid;plan uuid;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 begin draft:=(p_scope->>'draftId')::uuid;plan:=(p_scope->>'planId')::uuid;exception when others then raise exception 'Invalid scope' using errcode='22023';end;
 if draft is not null then
  if not exists(select 1 from public.pro_invoice_drafts where user_id=p_actor and id=draft) then return null;end if;
  return jsonb_build_object('dueCents',public.pro_payment_link_due(p_actor,draft),'hasWork',(select work_id is not null from public.pro_invoice_drafts where user_id=p_actor and id=draft),
   'links',coalesce((select jsonb_agg(public.pro_payment_link_json(l) order by l.created_at desc) from public.pro_payment_links l where l.owner_id=p_actor and l.draft_id=draft),'[]'));
 elsif plan is not null then
  if not exists(select 1 from public.pro_payment_plans where owner_id=p_actor and id=plan) then return null;end if;
  return jsonb_build_object('links',coalesce((select jsonb_agg(public.pro_payment_link_json(l) order by l.created_at desc) from public.pro_payment_links l where l.owner_id=p_actor and l.plan_id=plan),'[]'));
 end if;
 raise exception 'Invalid scope' using errcode='22023';
end $$;

create or replace function public.pro_payment_link_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_payment_link_actions;h text:=md5(p_input::text);l public.pro_payment_links;d public.pro_invoice_drafts;w public.pro_work;c public.pro_clients;
 p public.pro_payment_plans;st jsonb;item jsonb;amount bigint;acc jsonb;descr text;days integer;result jsonb;n_items integer;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-payment-link:'||p_actor::text,0));
 select * into receipt from public.pro_payment_link_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input_hash<>h then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 if act='create' then
  days:=(p_input->>'expiresInDays')::integer;
  if p_input->>'tokenHash' !~ '^[a-f0-9]{64}$' or days not between 1 and 60 or p_input->>'mode' not in('mock','sandbox','production') or jsonb_typeof(p_input->'methods')<>'array' then raise exception 'Invalid link' using errcode='22023';end if;
  if p_input->>'target'='invoice' then
   select * into d from public.pro_invoice_drafts where user_id=p_actor and id=(p_input->>'draftId')::uuid for update;
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   if d.work_id is null then raise exception 'Draft without job' using errcode='22023',hint='pro_payment_link_no_work';end if;
   if exists(select 1 from public.pro_invoice_draft_management m where m.user_id=p_actor and m.draft_id=d.id and m.archived) then raise exception 'Archived draft' using errcode='22023',hint='pro_payment_link_inactive';end if;
   select * into w from public.pro_work where user_id=p_actor and id=d.work_id;
   amount:=public.pro_payment_link_due(p_actor,d.id);descr:=d.title;
  elsif p_input->>'target'='installment' then
   select * into p from public.pro_payment_plans where owner_id=p_actor and id=(p_input->>'planId')::uuid for update;
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   if p.status<>'active' or p.revision<>(p_input->>'planRevision')::integer then raise exception 'Plan changed' using errcode='40001';end if;
   select * into w from public.pro_work where user_id=p_actor and id=p.work_id;
   st:=public.pro_payment_plan_state(p_actor,p.id,(now() at time zone 'America/Costa_Rica')::date);
   select i into item from jsonb_array_elements(st->'items') i where (i->>'seq')::integer=(p_input->>'seq')::integer;
   if item is null then raise exception 'Unknown installment' using errcode='22023';end if;
   n_items:=(select count(*) from jsonb_array_elements(st->'items') i where i->>'kind'='installment');
   acc:=public.pro_work_account(p_actor,p.work_id);
   amount:=greatest(least((item->>'amountCents')::bigint-(item->>'appliedCents')::bigint,coalesce((acc->>'balanceCents')::bigint,0)),0);
   if acc->>'agreedCents' is null then amount:=0;end if;
   descr:=left(case when item->>'kind'='down_payment' then case when p_input->>'language'='en' then 'Down payment' else 'Prima' end
    else case when p_input->>'language'='en' then 'Installment '||(select count(*) from jsonb_array_elements(st->'items') i where i->>'kind'='installment' and (i->>'seq')::integer<=(item->>'seq')::integer)||' of '||n_items
     else 'Cuota '||(select count(*) from jsonb_array_elements(st->'items') i where i->>'kind'='installment' and (i->>'seq')::integer<=(item->>'seq')::integer)||' de '||n_items end end||' · '||w.service,160);
  else raise exception 'Invalid target' using errcode='22023';end if;
  select * into c from public.pro_clients where user_id=p_actor and id=w."clientId";
  if w.cancelled or coalesce(c.archived,true) then raise exception 'Inactive job' using errcode='22023',hint='pro_payment_link_inactive';end if;
  if amount<1 then raise exception 'Nothing due' using errcode='22023',hint='pro_payment_link_nothing_due';end if;
  insert into public.pro_payment_links(owner_id,id,token_hash,target,draft_id,plan_id,plan_revision,installment_seq,work_id,client_id,amount_cents,description,provider,mode,methods,expires_at)
  values(p_actor,(p_input->>'linkId')::uuid,p_input->>'tokenHash',p_input->>'target',d.id,p.id,case when p.id is not null then p.revision end,case when p.id is not null then (p_input->>'seq')::integer end,
   w.id,w."clientId",amount,descr,'tilopay',p_input->>'mode',array(select jsonb_array_elements_text(p_input->'methods')),now()+make_interval(days=>days)) returning * into l;
 elsif act='cancel' then
  select * into l from public.pro_payment_links where owner_id=p_actor and id=(p_input->>'linkId')::uuid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if l.status<>'active' then raise exception 'Link not active' using errcode='40001';end if;
  if exists(select 1 from public.pro_payment_attempts a where a.owner_id=p_actor and a.link_id=l.id and a.status in('pending','requires_action') and a.created_at>now()-interval '30 minutes') then raise exception 'A payment is in progress' using errcode='22023',hint='pro_payment_link_in_progress';end if;
  if length(coalesce(trim(p_input->>'reason'),'')) not between 1 and 160 then raise exception 'Reason required' using errcode='22023';end if;
  update public.pro_payment_links set status='cancelled',cancelled_at=now(),cancel_reason=trim(p_input->>'reason') where owner_id=p_actor and id=l.id returning * into l;
 else raise exception 'Invalid link action' using errcode='22023';end if;
 result:=public.pro_payment_link_json(l);
 insert into public.pro_payment_link_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,h,result);
 return result;
exception when unique_violation then raise exception 'An active link already exists' using errcode='23505',hint='pro_payment_link_exists';
 when check_violation or invalid_text_representation or not_null_violation then raise exception 'Invalid link data' using errcode='22023';
end $$;

-- Public (hosted page): token hash only; no owner, job or customer identifiers leave the server.
create or replace function public.pro_payment_link_public(p_token_hash text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.pro_payment_links;biz text;open_attempt public.pro_payment_attempts;
begin
 select * into l from public.pro_payment_links where token_hash=p_token_hash;
 if not found or not public.pro_private_work_tools_enabled(l.owner_id) then return null;end if;
 select coalesce(nullif(trim(business_name),''),'ContrataCR') into biz from public.professionals where profile_id=l.owner_id;
 select * into open_attempt from public.pro_payment_attempts where owner_id=l.owner_id and link_id=l.id and status in('pending','requires_action') order by created_at desc limit 1;
 return jsonb_build_object('status',case when l.status='active' and l.expires_at<=now() then 'expired' else l.status end,'amountCents',l.amount_cents,'currency',l.currency,'description',l.description,
  'businessName',coalesce(biz,'ContrataCR'),'methods',to_jsonb(l.methods),'mode',l.mode,'expiresAt',l.expires_at,'paidAt',l.paid_at,
  'sinpePhone',coalesce((select c.config->>'sinpePhone' from public.pro_integration_connections c where c.owner_id=l.owner_id and c.provider='tilopay'),''),
  'openAttempt',case when open_attempt.id is null then null else jsonb_build_object('id',open_attempt.id,'method',open_attempt.method,'status',open_attempt.status) end,
  'lastFailure',(select a.failure_code from public.pro_payment_attempts a where a.owner_id=l.owner_id and a.link_id=l.id and a.status='failed' order by a.created_at desc limit 1));
end $$;
-- The server ran the processor adapter for this link and records the attempt it got back.
create or replace function public.pro_payment_attempt_record(p_token_hash text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare l public.pro_payment_links;a public.pro_payment_attempts;
begin
 select * into l from public.pro_payment_links where token_hash=p_token_hash for update;
 if not found or not public.pro_private_work_tools_enabled(l.owner_id) then raise exception 'Unknown link' using errcode='42501';end if;
 if l.status<>'active' or l.expires_at<=now() then raise exception 'Link not payable' using errcode='22023',hint='pro_payment_link_closed';end if;
 if not (p_input->>'method')=any(l.methods) then raise exception 'Method not offered' using errcode='22023';end if;
 if p_input->>'status' not in('pending','requires_action','failed') then raise exception 'Invalid attempt status' using errcode='22023';end if;
 insert into public.pro_payment_attempts(owner_id,id,link_id,provider,mode,processor_ref,method,status,amount_cents,card_last4,card_brand,sinpe_reference,failure_code)
 values(l.owner_id,(p_input->>'attemptId')::uuid,l.id,l.provider,l.mode,p_input->>'processorRef',p_input->>'method',p_input->>'status',l.amount_cents,nullif(p_input->>'cardLast4',''),nullif(p_input->>'cardBrand',''),
  nullif(p_input->>'sinpeReference',''),nullif(p_input->>'failureCode','')) returning * into a;
 return jsonb_build_object('attemptId',a.id,'status',a.status,'processorRef',a.processor_ref,'amountCents',a.amount_cents,'provider',a.provider,'mode',a.mode,'ownerId',a.owner_id,'linkId',l.id);
exception when unique_violation then raise exception 'Attempt already recorded' using errcode='23505';
 when check_violation or invalid_text_representation or not_null_violation then raise exception 'Invalid attempt' using errcode='22023';
end $$;
-- Open attempt of a link by id (3-D Secure step); only through the same token.
create or replace function public.pro_payment_attempt_open(p_token_hash text,p_attempt uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('attemptId',a.id,'status',a.status,'processorRef',a.processor_ref,'amountCents',a.amount_cents,'provider',a.provider,'mode',a.mode,'method',a.method,'ownerId',a.owner_id,'linkId',l.id)
 from public.pro_payment_links l join public.pro_payment_attempts a on a.owner_id=l.owner_id and a.link_id=l.id where l.token_hash=p_token_hash and a.id=p_attempt $$;
-- Post-security fixes (2026-11-13): a SINPE attempt is recorded «pending» with the SERVER-generated reference BEFORE
-- the processor is consulted with that same reference; when the processor does not confirm it (not found, amount or
-- currency mismatch, unavailable) the attempt is closed as «failed» here. Only pending SINPE attempts of this link.
create or replace function public.pro_payment_attempt_fail(p_token_hash text,p_attempt uuid,p_failure text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare a public.pro_payment_attempts;
begin
 if p_failure is null or p_failure!~'^[a-z_]{3,60}$' then raise exception 'Invalid failure code' using errcode='22023';end if;
 select a2.* into a from public.pro_payment_links l join public.pro_payment_attempts a2 on a2.owner_id=l.owner_id and a2.link_id=l.id
  where l.token_hash=p_token_hash and a2.id=p_attempt for update of a2;
 if not found then raise exception 'Unknown attempt' using errcode='P0002';end if;
 if a.method<>'sinpe' or a.status<>'pending' then raise exception 'Attempt is not an open SINPE attempt' using errcode='40001';end if;
 update public.pro_payment_attempts set status='failed',failure_code=p_failure where owner_id=a.owner_id and id=a.id returning * into a;
 return jsonb_build_object('attemptId',a.id,'status',a.status,'failureCode',a.failure_code);
end $$;
-- Event routing: which owner/attempt a processor reference belongs to (webhook handler).
create or replace function public.pro_payment_attempt_by_ref(p_provider text,p_ref text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('attemptId',a.id,'ownerId',a.owner_id,'status',a.status,'amountCents',a.amount_cents,'mode',a.mode,'method',a.method) from public.pro_payment_attempts a where a.provider=p_provider and a.processor_ref=p_ref $$;

-- Apply one inbox event exactly once (all in the caller's transaction). Payload (already redacted):
-- {type: payment.succeeded | payment.failed | payment.refunded, processorRef, amountCents, failureCode?}
create or replace function public.pro_payment_event_apply(p_webhook uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wh public.pro_integration_webhooks;a public.pro_payment_attempts;l public.pro_payment_links;t public.pro_payment_transactions;d public.pro_invoice_drafts;
 typ text;req uuid;rev integer;prev integer;review text;void_id uuid;today date:=(now() at time zone 'America/Costa_Rica')::date;label text;
begin
 select * into wh from public.pro_integration_webhooks where id=p_webhook for update;
 if not found then raise exception 'Unknown webhook' using errcode='22023';end if;
 if wh.status in('processed','ignored') then return jsonb_build_object('status',wh.status,'duplicate',true,'review',wh.last_error);end if;
 typ:=wh.event_type;
 select * into a from public.pro_payment_attempts where provider=wh.provider and processor_ref=wh.payload->>'processorRef' for update;
 if not found then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_reference' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_reference');
 end if;
 if wh.owner_id is null then update public.pro_integration_webhooks set owner_id=a.owner_id where id=wh.id;end if;
 if wh.mode<>a.mode then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='mode_mismatch' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','mode_mismatch');
 end if;
 select * into l from public.pro_payment_links where owner_id=a.owner_id and id=a.link_id for update;
 label:=left(case when a.method='sinpe' then 'Pago en línea SINPE Móvil · ' else 'Pago en línea con tarjeta · ' end||a.processor_ref,160);
 if typ='payment.succeeded' then
  if exists(select 1 from public.pro_payment_transactions where owner_id=a.owner_id and attempt_id=a.id and kind='payment') or a.status in('succeeded','refunded') then
   update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error='already_applied' where id=wh.id;
   return jsonb_build_object('status','processed','duplicate',true,'review',null);
  end if;
  if a.status not in('pending','requires_action') then
   update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='attempt_'||a.status where id=wh.id;
   return jsonb_build_object('status','ignored','duplicate',false,'review','attempt_'||a.status);
  end if;
  update public.pro_payment_attempts set status='succeeded' where owner_id=a.owner_id and id=a.id;
  req:=public.pro_payment_derived_uuid('ccr-online-payment:'||wh.provider||':'||wh.event_id);
  if coalesce((wh.payload->>'amountCents')::bigint,-1)<>a.amount_cents then review:='amount_mismatch';
  elsif l.status<>'active' then review:='link_'||l.status;
  else
   begin
    if l.target='invoice' then
     select * into d from public.pro_invoice_drafts where user_id=a.owner_id and id=l.draft_id;
     select coalesce((select revision from public.pro_invoice_payment_state where user_id=a.owner_id and draft_id=d.id),0) into prev;
     perform public.pro_invoice_payment_mutate(a.owner_id,jsonb_build_object('requestId',req,'draftId',d.id,'draftRevision',d.revision,'revision',prev,'action','apply','source','new',
      'amountCents',a.amount_cents,'receivedOn',to_char(today,'YYYY-MM-DD'),'method',case when a.method='sinpe' then 'sinpe' else 'card' end,'reference',label));
    else
     select revision into rev from public.pro_workspace_core where user_id=a.owner_id;
     perform public.pro_record_client_operation(a.owner_id,jsonb_build_object('actionId',req,'clientId',l.client_id,'workId',l.work_id,'kind','payment','amountCents',a.amount_cents,'note',label),rev);
    end if;
    if not exists(select 1 from public.pro_client_entries where user_id=a.owner_id and id=req and kind='payment') then raise exception 'Ledger payment missing' using errcode='22023';end if;
    insert into public.pro_payment_transactions(owner_id,id,provider,event_id,kind,attempt_id,link_id,entry_id,invoice_payment_id,amount_cents)
    values(a.owner_id,gen_random_uuid(),wh.provider,wh.event_id,'payment',a.id,l.id,req,case when l.target='invoice' then req end,a.amount_cents);
    update public.pro_payment_links set status='paid',paid_at=now() where owner_id=l.owner_id and id=l.id;
   exception when others then review:=left('ledger_refused: '||sqlerrm,280);
   end;
  end if;
  update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error=review where id=wh.id;
  return jsonb_build_object('status','processed','duplicate',false,'review',review,'entryId',case when review is null then req end);
 elsif typ='payment.failed' then
  if a.status in('pending','requires_action') then update public.pro_payment_attempts set status='failed',failure_code=left(coalesce(wh.payload->>'failureCode','declined'),60) where owner_id=a.owner_id and id=a.id;end if;
  update public.pro_integration_webhooks set status='processed',processed_at=now() where id=wh.id;
  return jsonb_build_object('status','processed','duplicate',false,'review',null);
 elsif typ='payment.refunded' then
  if a.status='refunded' or exists(select 1 from public.pro_payment_transactions where owner_id=a.owner_id and attempt_id=a.id and kind='refund') then
   update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error='already_refunded' where id=wh.id;
   return jsonb_build_object('status','processed','duplicate',true,'review',null);
  end if;
  if a.status<>'succeeded' then
   update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='attempt_'||a.status where id=wh.id;
   return jsonb_build_object('status','ignored','duplicate',false,'review','attempt_'||a.status);
  end if;
  update public.pro_payment_attempts set status='refunded' where owner_id=a.owner_id and id=a.id;
  select * into t from public.pro_payment_transactions where owner_id=a.owner_id and attempt_id=a.id and kind='payment';
  if t.id is null then
   -- Refund of money never booked (an exception): nothing to reverse in the ledger.
   update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error='refund_without_ledger' where id=wh.id;
   return jsonb_build_object('status','processed','duplicate',false,'review','refund_without_ledger');
  end if;
  select id into void_id from public.pro_client_entries where user_id=a.owner_id and reversal_id=t.entry_id and kind='payment_void';
  if void_id is null then
   void_id:=public.pro_payment_derived_uuid('ccr-online-refund:'||wh.provider||':'||wh.event_id);
   select revision into rev from public.pro_workspace_core where user_id=a.owner_id;
   perform public.pro_record_client_operation(a.owner_id,jsonb_build_object('actionId',void_id,'clientId',l.client_id,'workId',l.work_id,'kind','payment_void','entryId',t.entry_id,
    'note',left('Reembolso en línea · '||a.processor_ref||coalesce(' · '||(select r.reason from public.pro_payment_refund_requests r where r.owner_id=a.owner_id and r.transaction_id=t.id),''),160)),rev);
  end if;
  insert into public.pro_payment_transactions(owner_id,id,provider,event_id,kind,attempt_id,link_id,entry_id,amount_cents) values(a.owner_id,gen_random_uuid(),wh.provider,wh.event_id,'refund',a.id,l.id,void_id,t.amount_cents);
  update public.pro_integration_webhooks set status='processed',processed_at=now() where id=wh.id;
  return jsonb_build_object('status','processed','duplicate',false,'review',null,'entryId',void_id);
 end if;
 update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_type' where id=wh.id;
 return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_type');
end $$;

-- Owner asks for a refund of an online payment (the server then calls the processor adapter).
create or replace function public.pro_payment_refund_request(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare t public.pro_payment_transactions;a public.pro_payment_attempts;prior public.pro_payment_refund_requests;aid uuid;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 select * into t from public.pro_payment_transactions where owner_id=p_actor and id=(p_input->>'transactionId')::uuid and kind='payment';
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into a from public.pro_payment_attempts where owner_id=p_actor and id=t.attempt_id;
 select * into prior from public.pro_payment_refund_requests where owner_id=p_actor and transaction_id=t.id;
 if found then
  if prior.action_id<>aid then raise exception 'Refund already requested' using errcode='23505',hint='pro_payment_refund_exists';end if;
 else
  if a.status<>'succeeded' then raise exception 'Not refundable' using errcode='22023';end if;
  if length(coalesce(trim(p_input->>'reason'),'')) not between 1 and 160 then raise exception 'Reason required' using errcode='22023';end if;
  insert into public.pro_payment_refund_requests(owner_id,action_id,transaction_id,reason) values(p_actor,aid,t.id,trim(p_input->>'reason'));
 end if;
 return jsonb_build_object('transactionId',t.id,'processorRef',a.processor_ref,'provider',a.provider,'mode',a.mode,'amountCents',t.amount_cents,'status',a.status);
end $$;

-- Reconciliation: every attempt with its ledger booking, classified.
create or replace function public.pro_payment_reconciliation(p_actor uuid,p_filter text default 'all') returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rows jsonb;summ jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_filter not in('all','exceptions') then raise exception 'Invalid filter' using errcode='22023';end if;
 with base as(
  select a.*,l.description,l.target,l.draft_id,l.plan_id,l.work_id,l.status link_status,
   (select t.entry_id from public.pro_payment_transactions t where t.owner_id=a.owner_id and t.attempt_id=a.id and t.kind='payment') pay_entry,
   (select t.id from public.pro_payment_transactions t where t.owner_id=a.owner_id and t.attempt_id=a.id and t.kind='payment') pay_tx,
   (select t.entry_id from public.pro_payment_transactions t where t.owner_id=a.owner_id and t.attempt_id=a.id and t.kind='refund') refund_entry,
   (select w.last_error from public.pro_integration_webhooks w where w.provider=a.provider and w.payload->>'processorRef'=a.processor_ref and w.event_type='payment.succeeded' order by w.received_at desc limit 1) review,
   exists(select 1 from public.pro_payment_refund_requests r join public.pro_payment_transactions t on t.owner_id=r.owner_id and t.id=r.transaction_id where r.owner_id=a.owner_id and t.attempt_id=a.id) refund_requested
  from public.pro_payment_attempts a join public.pro_payment_links l on l.owner_id=a.owner_id and l.id=a.link_id where a.owner_id=p_actor
 ),classified as(
  select b.*,case
   when b.status='succeeded' and b.pay_entry is null then 'exception'
   when b.status='succeeded' and exists(select 1 from public.pro_client_entries v where v.user_id=b.owner_id and v.reversal_id=b.pay_entry and v.kind='payment_void') then 'exception'
   when b.status='refunded' and b.pay_entry is not null and b.refund_entry is null then 'exception'
   when b.status='refunded' then 'refunded' when b.status='succeeded' then 'matched'
   when b.status in('pending','requires_action') then 'pending' else 'failed' end as recon
  from base b
 )
 select coalesce((select jsonb_agg(jsonb_build_object('attemptId',id,'processorRef',processor_ref,'provider',provider,'mode',mode,'method',method,'status',status,'amountCents',amount_cents,'cardLast4',card_last4,
   'sinpeReference',sinpe_reference,'failureCode',failure_code,'description',description,'target',target,'draftId',draft_id,'planId',plan_id,'workId',work_id,'linkStatus',link_status,
   'entryId',pay_entry,'transactionId',pay_tx,'refundEntryId',refund_entry,'refundRequested',refund_requested,'review',review,'reconciliation',recon,'at',created_at) order by created_at desc)
   from (select * from classified where p_filter='all' or recon='exception' order by created_at desc limit 200) x),'[]'),
  (select jsonb_build_object(
   'receivedCents',coalesce(sum(amount_cents) filter(where status in('succeeded','refunded')),0),
   'bookedCents',coalesce(sum(amount_cents) filter(where recon='matched'),0),
   'refundedCents',coalesce(sum(amount_cents) filter(where recon='refunded'),0),
   'exceptions',count(*) filter(where recon='exception'),'pending',count(*) filter(where recon='pending'),'failed',count(*) filter(where recon='failed')) from classified)
 into rows,summ;
 return jsonb_build_object('items',rows,'summary',summ);
end $$;

do $$declare n text;begin foreach n in array array['pro_payment_links','pro_payment_attempts','pro_payment_transactions','pro_payment_refund_requests','pro_payment_link_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'pro\_payment\_link%' or p.proname like 'pro\_payment\_attempt%' or p.proname in('pro_payment_event_apply','pro_payment_refund_request','pro_payment_reconciliation','pro_payment_immutable','pro_payment_derived_uuid')) loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_payment_immutable(%' and f::text not like 'pro_payment_link_guard(%' and f::text not like 'pro_payment_attempt_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== integrations-providers-local.sql =====
-- LOCAL PRO ONLY. Round 6B (2026-11-13): new providers in the Round 6A integration framework.
-- * esign      = electronic signature (mock provider; DocuSign eSignature sandbox adapter, inactive)
-- * google     = Gmail / Google Calendar / Google Drive (OAuth 2.0 + PKCE)
-- * microsoft  = Outlook mail / Outlook calendar / OneDrive (Microsoft identity platform, OAuth 2.0 + PKCE)
-- * quickbooks = QuickBooks Online accounting (Intuit OAuth 2.0)
-- Same rules as 6A: mock by default, sandbox only with every env var, production only with the typed
-- confirmation AND PRO_INTEGRATIONS_ALLOW_PRODUCTION=1. This module only widens the provider lists and
-- re-creates the two framework functions that enumerate providers; no row is changed.
begin;

create or replace function public.pro_integration_provider_ids() returns text[]
language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['hacienda','tilopay','esign','google','microsoft','quickbooks']::text[] $$;

do $$declare t text;begin foreach t in array array['pro_integration_connections','pro_integration_requests','pro_integration_webhooks'] loop
 execute format('alter table public.%I drop constraint if exists %I',t,t||'_provider_check');
 execute format('alter table public.%I add constraint %I check(provider = any(public.pro_integration_provider_ids()))',t,t||'_provider_check');
end loop;end $$;

create or replace function public.pro_integration_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare out jsonb:='[]';p text;r public.pro_integration_connections;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 foreach p in array public.pro_integration_provider_ids() loop
  select * into r from public.pro_integration_connections where owner_id=p_actor and provider=p;
  if not found then r:=null;end if;
  out:=out||jsonb_build_array(public.pro_integration_connection_json(r,p));
 end loop;
 return jsonb_build_object('connections',out,
  'history',coalesce((select jsonb_agg(jsonb_build_object('provider',h.provider,'action',h.action,'fromMode',h.from_mode,'toMode',h.to_mode,'detail',h.detail,'at',h.created_at) order by h.created_at desc) from (select * from public.pro_integration_history where owner_id=p_actor order by created_at desc limit 20) h),'[]'),
  'requests',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'provider',q.provider,'mode',q.mode,'operation',q.operation,'target',q.target,'summary',q.summary,'statusCode',q.status_code,'outcome',q.outcome,'durationMs',q.duration_ms,'attempt',q.attempt,'correlation',q.correlation,'at',q.created_at) order by q.created_at desc) from (select * from public.pro_integration_requests where owner_id=p_actor order by created_at desc limit 30) q),'[]'),
  'webhooks',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'provider',w.provider,'mode',w.mode,'eventId',w.event_id,'eventType',w.event_type,'status',w.status,'attempts',w.attempts,'nextAttemptAt',w.next_attempt_at,'lastError',w.last_error,'receivedAt',w.received_at,'processedAt',w.processed_at) order by w.received_at desc) from (select * from public.pro_integration_webhooks where owner_id=p_actor order by received_at desc limit 30) w),'[]'));
end $$;

-- Same body as 6A; only the provider whitelist now comes from pro_integration_provider_ids().
create or replace function public.pro_integration_mutate(p_actor uuid,p_input jsonb,p_production_allowed boolean default false) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';prov text:=p_input->>'provider';aid uuid;receipt public.pro_integration_actions;r public.pro_integration_connections;
 next_mode text;rev integer;result jsonb;old_mode text;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or not coalesce(prov=any(public.pro_integration_provider_ids()),false) or act not in('set_mode','save_config','enable','disable','test') then raise exception 'Invalid integration action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-integration:'||p_actor::text,0));
 select * into receipt from public.pro_integration_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 insert into public.pro_integration_connections(owner_id,provider,revision) values(p_actor,prov,0) on conflict do nothing;
 select * into r from public.pro_integration_connections where owner_id=p_actor and provider=prov for update;
 old_mode:=r.mode;
 if act<>'test' then
  if jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid revision' using errcode='22023';end if;
  rev:=(p_input->>'revision')::integer;
  if rev is distinct from r.revision then raise exception 'Integration changed' using errcode='40001';end if;
 end if;
 if act='set_mode' then
  next_mode:=p_input->>'mode';
  if next_mode not in('mock','sandbox','production') then raise exception 'Invalid mode' using errcode='22023';end if;
  if next_mode='production' then
   if not coalesce(p_production_allowed,false) then raise exception 'Production integrations are not allowed on this server' using errcode='42501',hint='pro_integration_production_refused';end if;
   if p_input->>'confirm' is distinct from 'ACTIVAR PRODUCCION' then raise exception 'Production needs explicit confirmation' using errcode='22023',hint='pro_integration_production_confirm';end if;
  end if;
  update public.pro_integration_connections set mode=next_mode,production_confirmed_at=case when next_mode='production' then now() else null end,revision=revision+1,updated_at=now()
   where owner_id=p_actor and provider=prov returning * into r;
 elsif act='save_config' then
  if jsonb_typeof(p_input->'config')<>'object' or not public.pro_integration_config_safe(p_input->'config') then raise exception 'Config must be non-secret' using errcode='22023',hint='pro_integration_secret_config';end if;
  update public.pro_integration_connections set config=p_input->'config',revision=revision+1,updated_at=now() where owner_id=p_actor and provider=prov returning * into r;
 elsif act in('enable','disable') then
  update public.pro_integration_connections set enabled=(act='enable'),revision=revision+1,updated_at=now() where owner_id=p_actor and provider=prov returning * into r;
 else
  if jsonb_typeof(p_input->'ok')<>'boolean' or p_input->>'testMode' not in('mock','sandbox','production') or length(coalesce(p_input->>'message',''))>300 then raise exception 'Invalid test result' using errcode='22023';end if;
  update public.pro_integration_connections set last_test_at=now(),last_test_ok=(p_input->>'ok')::boolean,last_test_mode=p_input->>'testMode',last_test_message=nullif(p_input->>'message','')
   where owner_id=p_actor and provider=prov returning * into r;
 end if;
 insert into public.pro_integration_history(owner_id,id,provider,action,from_mode,to_mode,detail) values(p_actor,aid,prov,act,old_mode,r.mode,
  case when act='save_config' then jsonb_build_object('keys',(select coalesce(jsonb_agg(k order by k),'[]') from jsonb_object_keys(p_input->'config') k)) when act='test' then jsonb_build_object('ok',p_input->'ok','mode',p_input->>'testMode') else '{}'::jsonb end);
 result:=public.pro_integration_connection_json(r,prov);
 insert into public.pro_integration_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

revoke all on function public.pro_integration_provider_ids() from public,anon,authenticated;
grant execute on function public.pro_integration_provider_ids() to service_role;
revoke all on function public.pro_integration_read(uuid) from public,anon,authenticated;
grant execute on function public.pro_integration_read(uuid) to service_role;
revoke all on function public.pro_integration_mutate(uuid,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.pro_integration_mutate(uuid,jsonb,boolean) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== esign-local.sql =====
-- LOCAL PRO ONLY. Round 6B (2026-11-13): electronic signature requests (Houzz parity row 41).
-- * A request freezes ONE shared document: a contract version, a quote publication or a proposed/accepted
--   change order. Snapshot + SHA-256 are copied at creation and never change.
-- * State machine: created → sent → viewed → signed | declined | expired | cancelled (created/sent/viewed can
--   be cancelled; created → error → sent on retry). Finals are immutable. Events are append-only.
-- * Provider status arrives ONLY through the 6A webhook inbox (pro_integration_webhooks, provider 'esign'),
--   idempotent by event id; pro_esign_event_apply maps each event once and ignores out-of-order ones.
-- * «signed» stores the signed PDF and the audit certificate (bytea + SHA-256) in the same transaction;
--   artifacts can never be updated, and only the account-deletion cascade can remove them.
-- * The existing authenticated acceptance (contracts / quotes / change orders) is untouched: it stays the
--   fallback when no electronic signature is used.
-- Tables: RLS on, service_role only; functions security invoker, executable by service_role only.
begin;

create table if not exists public.pro_esign_requests(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 document_kind text not null check(document_kind in('contract','quote','work_change')),
 document_id uuid not null,
 document_label text not null check(length(document_label) between 1 and 200),
 document_hash text not null check(document_hash~'^[a-f0-9]{64}$'),
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object' and octet_length(snapshot::text)<=262144),
 signer_name text not null check(length(btrim(signer_name)) between 2 and 160),
 signer_email text not null check(length(signer_email)<=254 and signer_email~'^[^@\s]+@[^@\s]+\.[^@\s]+$'),
 language text not null default 'es' check(language in('es','en')),
 mode text not null check(mode in('mock','sandbox','production')),
 envelope_id text check(envelope_id is null or length(envelope_id) between 6 and 120),
 signer_token_hash text check(signer_token_hash is null or signer_token_hash~'^[a-f0-9]{64}$'),
 status text not null default 'created' check(status in('created','sent','viewed','signed','declined','expired','cancelled','error')),
 expires_at timestamptz not null,
 sent_at timestamptz,viewed_at timestamptz,completed_at timestamptz,
 decline_reason text check(decline_reason is null or length(decline_reason) between 1 and 500),
 last_error text check(last_error is null or length(last_error)<=300),
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),
 check(status in('created','error','cancelled') or envelope_id is not null),
 check(status<>'declined' or decline_reason is not null),
 check((status in('signed','declined','expired','cancelled'))=(completed_at is not null))
);
create unique index if not exists pro_esign_requests_global on public.pro_esign_requests(id);
create unique index if not exists pro_esign_requests_envelope on public.pro_esign_requests(mode,envelope_id) where envelope_id is not null;
create unique index if not exists pro_esign_requests_token on public.pro_esign_requests(signer_token_hash) where signer_token_hash is not null;
-- One live request per document (a new one can be sent once the previous one ended).
create unique index if not exists pro_esign_requests_live on public.pro_esign_requests(owner_id,document_kind,document_id) where status in('created','sent','viewed','error');
create index if not exists pro_esign_requests_document on public.pro_esign_requests(owner_id,document_kind,document_id,created_at desc);

create table if not exists public.pro_esign_events(
 owner_id uuid not null,request_id uuid not null,seq integer not null check(seq>0),
 status text not null check(status in('created','sent','viewed','signed','declined','expired','cancelled','error')),
 source text not null check(source in('owner','provider','system')),
 webhook_id uuid,detail jsonb not null default '{}' check(octet_length(detail::text)<=4096 and public.pro_integration_config_safe(detail)),
 at timestamptz not null default clock_timestamp(),
 primary key(owner_id,request_id,seq),foreign key(owner_id,request_id) references public.pro_esign_requests(owner_id,id) on delete cascade
);
create table if not exists public.pro_esign_artifacts(
 owner_id uuid not null,request_id uuid not null,
 kind text not null check(kind in('signed_pdf','certificate')),
 content bytea not null check(octet_length(content) between 64 and 10485760),
 sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,request_id,kind),foreign key(owner_id,request_id) references public.pro_esign_requests(owner_id,id) on delete cascade,
 check(sha256=encode(sha256(content),'hex'))
);
create table if not exists public.pro_esign_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);

-- Append-only rows: never updated; deleted only by the account-deletion cascade (owner profile gone).
create or replace function public.pro_esign_append_only() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='UPDATE' then raise exception 'Signature evidence is immutable' using errcode='23514';end if;
 if exists(select 1 from public.profiles where id=old.owner_id) then raise exception 'Signature evidence is immutable' using errcode='23514';end if;
 return old;
end $$;
do $$declare n text;begin foreach n in array array['pro_esign_events','pro_esign_artifacts','pro_esign_actions'] loop
 execute format('drop trigger if exists pro_esign_append_only on public.%I',n);
 execute format('create trigger pro_esign_append_only before update or delete on public.%I for each row execute function public.pro_esign_append_only()',n);
end loop;end $$;

create or replace function public.pro_esign_transition_ok(p_from text,p_to text) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_from
  when 'created' then p_to in('sent','error','cancelled')
  when 'error' then p_to in('sent','error','cancelled')
  when 'sent' then p_to in('viewed','signed','declined','expired','cancelled')
  when 'viewed' then p_to in('signed','declined','expired','cancelled')
  else false end $$;
-- Identity, snapshot and signer never change; status only follows the machine; finals are frozen;
-- «signed» needs both artifacts already stored in this transaction.
create or replace function public.pro_esign_request_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.owner_id<>old.owner_id or new.id<>old.id or new.document_kind<>old.document_kind or new.document_id<>old.document_id or new.document_hash<>old.document_hash
  or new.snapshot<>old.snapshot or new.signer_name<>old.signer_name or new.signer_email<>old.signer_email or new.mode<>old.mode or new.created_at<>old.created_at
  or old.envelope_id is not null and new.envelope_id is distinct from old.envelope_id then raise exception 'Signature request identity is immutable' using errcode='23514';end if;
 if new.status<>old.status and not public.pro_esign_transition_ok(old.status,new.status) then raise exception 'Invalid signature transition % -> %',old.status,new.status using errcode='23514';end if;
 if new.status=old.status and old.status in('signed','declined','expired','cancelled') then raise exception 'Signature request is final' using errcode='23514';end if;
 if new.status='signed' and (select count(*) from public.pro_esign_artifacts where owner_id=new.owner_id and request_id=new.id)<>2 then raise exception 'Signed requests need the signed PDF and the certificate' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_esign_request_guard on public.pro_esign_requests;
create trigger pro_esign_request_guard before update on public.pro_esign_requests for each row execute function public.pro_esign_request_guard();
create or replace function public.pro_esign_request_no_delete() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin if exists(select 1 from public.profiles where id=old.owner_id) then raise exception 'Signature requests are kept' using errcode='23514';end if;return old;end $$;
drop trigger if exists pro_esign_request_no_delete on public.pro_esign_requests;
create trigger pro_esign_request_no_delete before delete on public.pro_esign_requests for each row execute function public.pro_esign_request_no_delete();

create or replace function public.pro_esign_log(p_owner uuid,p_request uuid,p_status text,p_source text,p_webhook uuid,p_detail jsonb) returns void
language sql security invoker set search_path=public,pg_temp as $$
 insert into public.pro_esign_events(owner_id,request_id,seq,status,source,webhook_id,detail)
 values(p_owner,p_request,coalesce((select max(seq) from public.pro_esign_events where owner_id=p_owner and request_id=p_request),0)+1,p_status,p_source,p_webhook,coalesce(p_detail,'{}')) $$;

-- Frozen document of one signable object (owner only). Raises 22023 with hint pro_esign_not_signable.
create or replace function public.pro_esign_document(p_actor uuid,p_kind text,p_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare c public.pro_contracts;v public.pro_contract_versions;pub public.pro_private_estimate_publications;st text;ch public.pro_work_changes;w public.pro_work;cl public.pro_clients;content jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_kind='contract' then
  select * into c from public.pro_contracts where owner_id=p_actor and id=p_id;
  if not found then raise exception 'Document unavailable' using errcode='P0002';end if;
  if c.status not in('shared','accepted') or c.latest_version is null then raise exception 'Contract must be shared' using errcode='22023',hint='pro_esign_not_signable';end if;
  select * into v from public.pro_contract_versions where owner_id=p_actor and contract_id=c.id and version=c.latest_version;
  select * into w from public.pro_work where user_id=p_actor and id=c.work_id;
  select * into cl from public.pro_clients where user_id=p_actor and id=w."clientId";
  return jsonb_build_object('kind','contract','documentId',c.id,'label',left((v.content->>'code')||' · '||(v.content->>'title'),200),'title',v.content->>'title','version',v.version,
   'clientName',coalesce(v.recipient_name,cl.name),'clientEmail',coalesce(cl.email,''),'language',c.language,'currency',coalesce(v.content->'estimate'->>'currency','CRC'),
   'totalCents',(v.content->'estimate'->>'totalCents')::bigint,'content',v.content,'contentHash',v.content_hash);
 elsif p_kind='quote' then
  select * into pub from public.pro_private_estimate_publications where owner_id=p_actor and id=p_id;
  if not found then raise exception 'Document unavailable' using errcode='P0002';end if;
  select status into st from public.pro_private_estimate_publication_states where publication_id=pub.id;
  if st not in('awaiting_claim','shared','changes_requested','accepted') then raise exception 'Quote must be shared' using errcode='22023',hint='pro_esign_not_signable';end if;
  select * into cl from public.pro_clients where user_id=p_actor and id=pub.client_id;
  return jsonb_build_object('kind','quote','documentId',pub.id,'label',left('COT-'||upper(left(pub.estimate_id::text,8))||' v'||pub.version||' · '||(pub.content->>'title'),200),'title',pub.content->>'title','version',pub.version,
   'clientName',coalesce(pub.content->'customer'->>'name',cl.name),'clientEmail',coalesce(cl.email,''),'language','es','currency',coalesce(pub.content->>'currency','CRC'),
   'totalCents',(pub.content->>'totalCents')::bigint,'content',pub.content,'contentHash',pub.content_hash);
 elsif p_kind='work_change' then
  select * into ch from public.pro_work_changes where owner_id=p_actor and id=p_id;
  if not found then raise exception 'Document unavailable' using errcode='P0002';end if;
  if ch.status not in('proposed','accepted') then raise exception 'Change must be proposed' using errcode='22023',hint='pro_esign_not_signable';end if;
  select * into w from public.pro_work where user_id=p_actor and id=ch.work_id;
  select * into cl from public.pro_clients where user_id=p_actor and id=w."clientId";
  content:=jsonb_build_object('reason',ch.reason,'lines',ch.lines,'baseCents',ch.base_cents,'deltaCents',ch.delta_cents,'totalCents',ch.total_cents,'project',w.service,'proposedAt',ch.created_at);
  return jsonb_build_object('kind','work_change','documentId',ch.id,'label',left('CAMBIO · '||ch.reason,200),'title',ch.reason,'version',ch.revision,
   'clientName',coalesce(cl.name,w.client),'clientEmail',coalesce(cl.email,''),'language','es','currency','CRC','totalCents',ch.total_cents,'content',content,
   'contentHash',encode(sha256(convert_to(content::text,'UTF8')),'hex'));
 end if;
 raise exception 'Invalid document kind' using errcode='22023';
end $$;

create or replace function public.pro_esign_json(r public.pro_esign_requests) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'documentKind',r.document_kind,'documentId',r.document_id,'documentLabel',r.document_label,'documentHash',r.document_hash,
  'signerName',r.signer_name,'signerEmail',r.signer_email,'language',r.language,'mode',r.mode,'envelopeId',r.envelope_id,'status',r.status,'expiresAt',r.expires_at,
  'sentAt',r.sent_at,'viewedAt',r.viewed_at,'completedAt',r.completed_at,'declineReason',r.decline_reason,'lastError',r.last_error,'revision',r.revision,'createdAt',r.created_at,
  'events',coalesce((select jsonb_agg(jsonb_build_object('seq',e.seq,'status',e.status,'source',e.source,'detail',e.detail,'at',e.at) order by e.seq) from public.pro_esign_events e where e.owner_id=r.owner_id and e.request_id=r.id),'[]'),
  'artifacts',coalesce((select jsonb_agg(jsonb_build_object('kind',a.kind,'sha256',a.sha256,'bytes',octet_length(a.content),'createdAt',a.created_at) order by a.kind) from public.pro_esign_artifacts a where a.owner_id=r.owner_id and a.request_id=r.id),'[]')) $$;

-- Requests past their deadline expire (system event). Called before every owner read.
create or replace function public.pro_esign_expire_due(p_actor uuid) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.pro_esign_requests;n integer:=0;
begin
 for r in select * from public.pro_esign_requests where owner_id=p_actor and status in('sent','viewed') and expires_at<=now() for update skip locked loop
  update public.pro_esign_requests set status='expired',completed_at=now(),revision=revision+1,updated_at=now() where owner_id=r.owner_id and id=r.id;
  perform public.pro_esign_log(r.owner_id,r.id,'expired','system',null,jsonb_build_object('expiresAt',r.expires_at));n:=n+1;
 end loop;
 return n;
end $$;

create or replace function public.pro_esign_read(p_actor uuid,p_kind text,p_id uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare doc jsonb;blocked text;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 perform public.pro_esign_expire_due(p_actor);
 begin doc:=public.pro_esign_document(p_actor,p_kind,p_id)-'content';
 exception when sqlstate '22023' then blocked:='not_signable';doc:=null;end;
 return jsonb_build_object('document',doc,'blocked',blocked,
  'requests',coalesce((select jsonb_agg(public.pro_esign_json(r) order by r.created_at desc) from public.pro_esign_requests r where r.owner_id=p_actor and r.document_kind=p_kind and r.document_id=p_id),'[]'));
end $$;

-- create: freezes the document now (owner-confirmed signer), idempotent by actionId.
create or replace function public.pro_esign_create(p_actor uuid,p_input jsonb,p_mode text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_esign_actions;doc jsonb;rid uuid;r public.pro_esign_requests;days integer;result jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or p_input->>'action'<>'create' or p_mode not in('mock','sandbox','production') then raise exception 'Invalid signature action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'documentId')::uuid;exception when others then raise exception 'Invalid ids' using errcode='22023';end;
 if aid is null or rid is null then raise exception 'Invalid ids' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-esign:'||p_actor::text,0));
 select * into receipt from public.pro_esign_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 days:=coalesce((p_input->>'expiryDays')::integer,14);
 if days not between 1 and 60 then raise exception 'Invalid expiry' using errcode='22023';end if;
 doc:=public.pro_esign_document(p_actor,p_input->>'documentKind',rid);
 if exists(select 1 from public.pro_esign_requests where owner_id=p_actor and document_kind=doc->>'kind' and document_id=rid and status in('created','sent','viewed','error')) then
  raise exception 'A signature request is already open for this document' using errcode='23505',hint='pro_esign_open';end if;
 insert into public.pro_esign_requests(owner_id,id,document_kind,document_id,document_label,document_hash,snapshot,signer_name,signer_email,language,mode,expires_at)
 values(p_actor,gen_random_uuid(),doc->>'kind',rid,doc->>'label',doc->>'contentHash',doc,btrim(p_input->>'signerName'),lower(btrim(p_input->>'signerEmail')),
  case when p_input->>'language' in('es','en') then p_input->>'language' else coalesce(doc->>'language','es') end,p_mode,now()+make_interval(days=>days)) returning * into r;
 -- The hash lives on the request row; event details stay free of long digit runs (redaction guard).
 perform public.pro_esign_log(p_actor,r.id,'created','owner',null,jsonb_build_object('mode',p_mode));
 result:=public.pro_esign_json(r)||jsonb_build_object('snapshot',r.snapshot);
 insert into public.pro_esign_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,jsonb_build_object('id',r.id));
 return result;
exception when check_violation then raise exception 'Invalid signer' using errcode='22023';
end $$;

-- The server reports the provider call (send). ok → sent with envelope id; failure → error (retryable).
create or replace function public.pro_esign_mark_sent(p_actor uuid,p_id uuid,p_ok boolean,p_envelope text,p_token_hash text,p_error text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.pro_esign_requests;
begin
 select * into r from public.pro_esign_requests where owner_id=p_actor and id=p_id for update;
 if not found then raise exception 'Unknown request' using errcode='P0002';end if;
 if r.status not in('created','error') then return public.pro_esign_json(r);end if;
 if p_ok then
  update public.pro_esign_requests set status='sent',envelope_id=p_envelope,signer_token_hash=p_token_hash,sent_at=now(),last_error=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=p_id returning * into r;
  perform public.pro_esign_log(p_actor,p_id,'sent','owner',null,jsonb_build_object('envelopeId',p_envelope));
 else
  update public.pro_esign_requests set status='error',last_error=left(coalesce(p_error,'error'),300),revision=revision+1,updated_at=now() where owner_id=p_actor and id=p_id returning * into r;
  perform public.pro_esign_log(p_actor,p_id,'error','system',null,jsonb_build_object('error',left(coalesce(p_error,'error'),200)));
 end if;
 return public.pro_esign_json(r);
end $$;

create or replace function public.pro_esign_cancel(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;rid uuid;receipt public.pro_esign_actions;r public.pro_esign_requests;result jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 begin aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid ids' using errcode='22023';end;
 if aid is null or rid is null or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid cancel' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-esign:'||p_actor::text,0));
 select * into receipt from public.pro_esign_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 select * into r from public.pro_esign_requests where owner_id=p_actor and id=rid for update;
 if not found then raise exception 'Unknown request' using errcode='P0002';end if;
 if r.revision<>(p_input->>'revision')::integer then raise exception 'Signature request changed' using errcode='40001';end if;
 if r.status not in('created','sent','viewed','error') then raise exception 'Signature request is final' using errcode='22023',hint='pro_esign_final';end if;
 update public.pro_esign_requests set status='cancelled',completed_at=now(),revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
 perform public.pro_esign_log(p_actor,rid,'cancelled','owner',null,'{}');
 result:=public.pro_esign_json(r);
 insert into public.pro_esign_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,jsonb_build_object('id',r.id,'status',r.status));
 return result;
end $$;

-- Request behind a provider envelope (webhook routing; also tells the server which mode/owner it belongs to).
create or replace function public.pro_esign_by_envelope(p_mode text,p_envelope text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('ownerId',owner_id,'id',id,'status',status,'mode',mode,'snapshot',snapshot,'signerName',signer_name,'signerEmail',signer_email,'language',language,
  'documentHash',document_hash,'createdAt',created_at,'sentAt',sent_at,'viewedAt',viewed_at,'expiresAt',expires_at,'envelopeId',envelope_id)
 from public.pro_esign_requests where mode=p_mode and envelope_id=p_envelope $$;
-- Mock signer page: only mock-mode requests, by the hash of the one-time signer link.
create or replace function public.pro_esign_signer_view(p_token_hash text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('envelopeId',envelope_id,'status',status,'label',document_label,'documentHash',document_hash,'signerName',signer_name,'language',language,'expiresAt',expires_at,
  'title',snapshot->>'title','totalCents',snapshot->'totalCents','currency',snapshot->>'currency','content',snapshot->'content','kind',document_kind)
 from public.pro_esign_requests where signer_token_hash=p_token_hash and mode='mock' $$;

-- Applies one inbox event. Payload: {envelopeId, status: sent|delivered|completed|declined|voided|expired, reason?, at}.
-- completed needs p_pdf and p_certificate (fetched by the server from the provider) and stores them first.
create or replace function public.pro_esign_event_apply(p_webhook uuid,p_pdf bytea default null,p_certificate bytea default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wh public.pro_integration_webhooks;r public.pro_esign_requests;target text;ps text;
begin
 select * into wh from public.pro_integration_webhooks where id=p_webhook and provider='esign' for update;
 if not found then raise exception 'Unknown webhook' using errcode='22023';end if;
 if wh.status in('processed','ignored') then return jsonb_build_object('status',wh.status,'duplicate',true,'review',wh.last_error);end if;
 select * into r from public.pro_esign_requests where mode=wh.mode and envelope_id=wh.payload->>'envelopeId' for update;
 if not found then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_envelope' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_envelope');
 end if;
 if wh.owner_id is null then update public.pro_integration_webhooks set owner_id=r.owner_id where id=wh.id;end if;
 ps:=wh.payload->>'status';
 target:=case ps when 'delivered' then 'viewed' when 'completed' then 'signed' when 'declined' then 'declined' when 'voided' then 'cancelled' when 'expired' then 'expired' when 'sent' then 'sent' else null end;
 if target is null then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_status' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_status');
 end if;
 if r.status=target then
  update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error='already_applied' where id=wh.id;
  return jsonb_build_object('status','processed','duplicate',true,'review',null,'request',r.id);
 end if;
 if not public.pro_esign_transition_ok(r.status,target) then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error=left('out_of_order_'||r.status||'_'||target,300) where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','out_of_order','request',r.id);
 end if;
 if target='signed' then
  if p_pdf is null or p_certificate is null then raise exception 'Completed envelope without documents' using errcode='22023',hint='pro_esign_documents_missing';end if;
  insert into public.pro_esign_artifacts(owner_id,request_id,kind,content,sha256) values
   (r.owner_id,r.id,'signed_pdf',p_pdf,encode(sha256(p_pdf),'hex')),(r.owner_id,r.id,'certificate',p_certificate,encode(sha256(p_certificate),'hex'));
 end if;
 update public.pro_esign_requests set status=target,
  viewed_at=case when target='viewed' then coalesce(viewed_at,now()) else viewed_at end,
  completed_at=case when target in('signed','declined','expired','cancelled') then now() else completed_at end,
  decline_reason=case when target='declined' then left(coalesce(nullif(btrim(wh.payload->>'reason'),''),'Sin motivo'),500) else decline_reason end,
  revision=revision+1,updated_at=now() where owner_id=r.owner_id and id=r.id returning * into r;
 perform public.pro_esign_log(r.owner_id,r.id,target,'provider',wh.id,jsonb_build_object('event',wh.event_id,'providerStatus',ps));
 update public.pro_integration_webhooks set status='processed',processed_at=now() where id=wh.id;
 return jsonb_build_object('status','processed','duplicate',false,'review',null,'request',r.id,'requestStatus',r.status);
end $$;

create or replace function public.pro_esign_artifact(p_actor uuid,p_id uuid,p_kind text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare a public.pro_esign_artifacts;r public.pro_esign_requests;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_esign_requests where owner_id=p_actor and id=p_id;
 if not found then raise exception 'Unknown request' using errcode='P0002';end if;
 select * into a from public.pro_esign_artifacts where owner_id=p_actor and request_id=p_id and kind=p_kind;
 if not found then raise exception 'Artifact unavailable' using errcode='P0002';end if;
 return jsonb_build_object('base64',encode(a.content,'base64'),'sha256',a.sha256,'label',r.document_label,'mode',r.mode);
end $$;

do $$declare n text;begin foreach n in array array['pro_esign_requests','pro_esign_events','pro_esign_artifacts','pro_esign_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_esign\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_esign_append_only(%' and f::text not like 'pro_esign_request_guard(%' and f::text not like 'pro_esign_request_no_delete(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;
